window.G12_SHORT_QUESTIONS = [[{"label":"Rev.1","question":[[{"text":" Under what condition the angular acceleration of a rotating object is equal to zero?"}]],"answer":[[{"text":"  The angular acceleration of a rotating object is equal to zero when the object is rotating with constant angular velocity."}],[{"text":"[OR]  For constant angular velocity, "}],[{"math":true,"tex":"\\omega ","plain":"ω"}],[{"text":" = "}],[{"math":true,"tex":"\\omega _{0}","plain":"ω₀"}],[{"text":" = constant"}],[{"math":true,"tex":"∴\\alpha ","plain":"∴α"}],[{"text":" = "}],[{"math":true,"tex":"\\frac{\\omega  - \\omega _{0} }{t}","plain":"(ω - ω₀ )/(t)"}],[{"text":" = "}],[{"math":true,"tex":"\\frac{0 }{t}","plain":"(0 )/(t)"}],[{"text":" = 0"}]]},{"label":"No.3","question":[[{"text":"  Choose the correct answer. The angular acceleration is equal to zero when ……"}],[{"text":"  A. There is no change in angular speed "}],[{"text":"  B. There is no change in the direction of the rotation "}],[{"text":"  C. There is no change in angular velocity "}]],"answer":[[{"text":"  C."}]]},{"label":"No.4","question":[[{"text":"  Which of the following correctly defines angular velocity? "}],[{"text":" A. Angular velocity is the rate of rotation with respect to the angular speed. "}],[{"text":" B. Angular velocity is the rate of rotation with respect to the displacement. "}],[{"text":" C. Angular velocity is the rate of change of angular displacement with respect to time."}]],"answer":[[{"text":"  C."}]]},{"label":"Rev.3","question":[[{"text":" In circular motion, how is a tangential acceleration produced?"}]],"answer":[[{"text":"  In circular motion, if the magnitude of the angular velocity of a rotating object change, the magnitude of the linear velocity will also change and the object will have a tangential acceleration. "}]]},{"label":"Rev.4","question":[[{"text":" On a rotating carousel, a child sits on a horse near the outer edge, and another child sits on a lion halfway out from the centre. "}],[{"text":"  (i) Which child has the greater linear velocity? "}],[{"text":"  (ii) Which child has the greater angular velocity? "}]],"answer":[[{"text":"  (i) A child sits on a horse near the outer edge has the greater linear velocity. "}],[{"text":"  (ii) Both children have the same angular velocity."}]]},{"label":"No.1","question":[[{"text":"  Consider a rotating circular plate of a lathe machine. Are the angular and tangential speeds at any point on the plate the same? Explain. "}]],"answer":[[{"text":"  The angular speeds of all the points will be the same. "}],[{"text":"  Since v = r ω,"}],[{"text":"  The tangential speeds of different points will not be the same. The farther the point from the centre of rotation, the greater will be the tangential speed of that point."}]]},{"label":"Rev.5","question":[[{"text":" Suppose a piece of food is on the edge of a rotating microwave oven plate. Does it experience tangential acceleration, centripetal acceleration or both when "}],[{"text":"  (i) the plate starts to spin faster? "}],[{"text":"  (ii) the plate rotates at constant angular velocity? "}],[{"text":"  (iii) the plate slows down to stop? "}]],"answer":[[{"text":"  (i) Both tangential acceleration and centripetal acceleration will have  "}],[{"text":"  (ii) Only centripetal acceleration will have"}],[{"text":"  (iii) Both tangential acceleration and centripetal acceleration will have"}]]},{"label":"No.2","question":[[{"text":"  Why is the centripetal acceleration produced in a circular motion?"}]],"answer":[[{"text":"  The direction of the linear velocity continuously changes as the object moves around the circle. The change in direction of the linear velocity constitutes the centripetal acceleration."}]]}],[{"label":"No.1","question":[[{"text":"  Imagine a car driving over a hillock at a constant speed. Once the car has reached the apex of the hillock, does it have the acceleration? If so, what is the direction of the acceleration? "}]],"answer":[[{"text":"  Yes, it has centripetal acceleration. It is directed toward the centre of the hillock."}]]},{"label":"No.3","question":[[{"text":"  An object is in a uniform circular motion. Which of the following statements must be true?"}],[{"text":"  A. The net force acting on the object is zero. "}],[{"text":"  B. The velocity of the object is constant."}],[{"text":"  C. The speed of the object is constant. "}],[{"text":"  D. The acceleration of the object is constant. "}]],"answer":[[{"text":"  C."}]]},{"label":"No.4","question":[[{"text":"  For an object moving in a circle with constant angular velocity, what is the direction of acceleration of the object?"}]],"answer":[[{"text":"  The direction of the acceleration of the object is toward the centre of the circular path."}]]},{"label":"Rev.2","question":[[{"text":" Choose the correct answer. "}],[{"text":"  A ball attached to a string is whirled around a vertical circle. At the bottom of the arc, "}],[{"text":"  A. It has no net force. "}],[{"text":"  B. it has a net force acting upward. "}],[{"text":"  C. it has a net force acting downward."}]],"answer":[[{"text":"  B."}]]},{"label":"No.5","question":[[{"text":"  When a bob is swinging in the vertical circle, at which point on the circular part is the tension in the rope the greatest? "}]],"answer":[[{"text":"  The lowest point on the circular part, the tension in the rope is the greatest."}]]},{"label":"Rev.3","question":[[{"text":"FNFNyFNx"},{"text":" When a skater forms a circle, he has to lean inwards. Explain with a force diagram."}]],"answer":[[{"text":"  "},{"math":true,"tex":"F_{N}","plain":"F_(N)"},{"text":" = normal force"}],[{"text":"  "},{"math":true,"tex":"F_{Nx}","plain":"F_(Nx)"},{"text":" = x-component of normal force"}],[{"text":"  "},{"math":true,"tex":"F_{Ny}","plain":"F_(Ny)"},{"text":" = y-component of normal force"}],[{"text":"  "},{"math":true,"tex":"F_{Nx}","plain":"F_(Nx)"},{"text":" provides the centripetal force."}],[{"text":"  "},{"math":true,"tex":"F_{Ny}","plain":"F_(Ny)"},{"text":" balances the weight."}]]},{"label":"No.2","question":[[{"text":"  Does the centripetal force and the centrifugal force constitute an action-reaction pair? Explain."}]],"answer":[[{"text":"  No, the centripetal force and the centrifugal force does not constitute an action-reaction pair."}],[{"text":"  Centripetal force is the force acting on an object in circular motion which is directed towards the axis of rotation or centre of curvature."}],[{"text":"  Centrifugal force in a circular motion is not a real force; it acts radially away from the centre of the circle. It results from the effect of inertia."}]]}],[{"label":"Rev.1","question":[[{"text":" Is motor car brake oil compressible or non-compressible? "}]],"answer":[[{"text":"  Motor car brake oil is non-compressible."}]]},{"label":"Rev.2","question":[[{"text":" Are gases compressible or non-compressible? "}]],"answer":[[{"text":"  Gases are compressible."}]]},{"label":"Rev.3","question":[[{"text":" What is the difference between laminar flow and turbulent flow?"}]],"answer":[[{"text":" | Laminar flow | Turbulent flow"}],[{"text":"Fluid particles are moving steady in smooth paths in layers. | The flow or path of the fluid particles are irregular."}],[{"text":"Streamlines do not cross each other. | Streamlines cross each other."}],[{"text":"Every fluid particle arriving at a given point has the same velocity. | The speed of the fluid at a point is continuously undergoing changes in both magnitude and direction."}],[{"text":"Laminar flows are smooth and streamlined. | Turbulent flows are irregular and chaotic."}]]},{"label":"Rev.4","question":[[{"text":" At a river junction, water streams are whirling; is it laminar or turbulent? "}]],"answer":[[{"text":"  At a river junction, water streams are whirling, so it is turbulent flow."}]]},{"label":"Rev.5","question":[[{"text":" Why does the river flow faster in passing the defile (narrow river passage)? "}]],"answer":[[{"text":"  The river flows faster in passing the defile (narrow river passage) because volume flow rate of water remains approximately constant. Equal volume flow rate with narrower passage indicates increasing velocity."}],[{"text":"[OR]  By using equation of continuity,  Av = constant "}],[{"text":"  A₁v₁ = A₂v₂ "}],[{"text":"  If A₂ < A₁, then v₂ > v₁"}],[{"text":"  So, the river flow faster in passing the defile (narrow river passage)."}]]},{"label":"No.1","question":[[{"text":"  How are the flow rate and fluid velocity related? "}]],"answer":[[{"text":"  The volume flow rate, "}],[{"math":true,"tex":"\\frac{V}{t}","plain":"(V)/(t)"}],[{"text":" = A v. The flow rate is directly proportional to the fluid velocity."}],[{"math":true,"tex":"\\frac{V}{t}","plain":"(V)/(t)"}],[{"text":" = volume flow rate, A = the cross-sectional area of the flow tube, "}],[{"text":"       v = velocity of the fluid"}]]},{"label":"Rev.7","question":[[{"text":" As water in a level pipe pass from narrower cross-sectional area of pipe to a wider cross-sectional area, does the pressure change? Explain. "}]],"answer":[[{"text":" | Yes, pressure change. \nAccording to Bernoulli's theorem, the water has to move more quickly through the narrower pipe in order to maintain the same flow rate. This increase in the water's kinetic energy causes the pressure to decrease."}],[{"text":"[OR] | Let section 1 be narrower section, section 2 be the wider section.\nA1 < A2, v1 > v2   for level pipe, h1 = h2"}],[{"text":"By using Bernoulli’s theorem,"}],[{"text":"p1 + "}],[{"math":true,"tex":"\\frac{1}{2}","plain":"(1)/(2)"}],[{"math":true,"tex":"\\rho ","plain":"ρ"}],[{"math":true,"tex":"v_{1}^{2}","plain":"v₁²"}],[{"text":" + "}],[{"math":true,"tex":"\\rho ","plain":"ρ"}],[{"text":" g h1 | = | p2 + "}],[{"math":true,"tex":"\\frac{1}{2}","plain":"(1)/(2)"}],[{"math":true,"tex":"\\rho ","plain":"ρ"}],[{"math":true,"tex":"v_{2}^{2}","plain":"v₂²"}],[{"text":" + "}],[{"math":true,"tex":"\\rho ","plain":"ρ"}],[{"text":" g h2"}],[{"text":"p1 + "}],[{"math":true,"tex":"\\frac{1}{2}","plain":"(1)/(2)"}],[{"math":true,"tex":"\\rho ","plain":"ρ"}],[{"math":true,"tex":"v_{1}^{2}","plain":"v₁²"}],[{"text":" | = | p2 + "}],[{"math":true,"tex":"\\frac{1}{2}","plain":"(1)/(2)"}],[{"math":true,"tex":"\\rho ","plain":"ρ"}],[{"math":true,"tex":"v_{2}^{2}","plain":"v₂²"}],[{"text":"Since, v1 > v2 ,               "}],[{"math":true,"tex":"\\frac{1}{2}","plain":"(1)/(2)"}],[{"math":true,"tex":"\\rho ","plain":"ρ"}],[{"math":true,"tex":"v_{1}^{2}","plain":"v₁²"}],[{"text":" | > | "}],[{"math":true,"tex":"\\frac{1}{2}","plain":"(1)/(2)"}],[{"math":true,"tex":"\\rho ","plain":"ρ"}],[{"math":true,"tex":"v_{2}^{2}","plain":"v₂²"}],[{"text":"   and p1 < p2"}],[{"text":"The pressure will be changed when water in a level pipe pass from narrower cross-sectional area of pipe to a wider cross-sectional area."}]]},{"label":"No.2","question":[[{"text":"  A perfume bottle or atomizer sprays the fluid that is in the bottle. How does the fluid rise in the vertical tube?"}]],"answer":[[{"text":" Spraying a perfume bottle or atomizer works on the Bernoulli's principle. By pressing piston, fast moving air over the vertical tube causes low air pressure. The liquid pressure inside the bottle will be higher. This will draw the liquid into the tube."}]]},{"label":"Rev.9","question":[[{"text":" Can fluid flow from lower pressure to higher pressure?"}]],"answer":[[{"text":"  Yes, fluid can flow from lower pressure to higher pressure by applying external force."}]]},{"label":"Rev.11","question":[[{"text":" On which factors does the viscosity of a liquid depend? "}]],"answer":[[{"text":" The viscosity of a liquid depends on (i) Intermolecular forces of attraction "}],[{"text":"   (ii) Temperature"}]]},{"label":"Rev.12","question":[[{"text":" How does temperature affect the viscosity of a fluid? "}]],"answer":[[{"text":"  The viscosity of liquids decreases rapidly with an increase in temperature. "}],[{"text":"  The viscosity of gases increases with an increase in temperature."}]]},{"label":"Rev.13","question":[[{"text":" Water rises in a capillary tube, whereas mercury falls in the same tube. Explain. "}]],"answer":[[{"text":"  Since cohesive forces between mercury molecules are larger than adhesive force between mercury and material of capillary tube, mercury falls in capillary tube."}],[{"text":"  Since adhesive forces between water and material of capillary tube are larger than cohesive force between water molecules, water rises in capillary tube."}]]},{"label":"No.10","question":[[{"text":" Which force causes capillary action rise? "}]],"answer":[[{"text":"  Greater adhesive force between liquid molecules and material of capillary tube than cohesive force between liquid molecules causes capillary action rise."}]]},{"label":"No.11","question":[[{"text":" How does the temperature affect capillary action? "}],[{"text":"  h = "}],[{"math":true,"tex":"\\frac{2 γ\\cos \\theta }{\\rho  g r}","plain":"(2 γcosθ)/(ρ g r)"}],[{"math":true,"tex":"\\to ","plain":"→"}],[{"text":"  h "}],[{"math":true,"tex":"\\propto ","plain":"∝"}],[{"math":true,"tex":"γ","plain":"γ"}],[{"math":true,"tex":"γ","plain":"γ"}],[{"text":" = "}],[{"math":true,"tex":"\\frac{F}{l}","plain":"(F)/(l)"}],[{"text":" = "}],[{"math":true,"tex":"\\frac{\\rho  V g}{l}  \\to   γ","plain":"(ρ V g)/(l)  →  γ"}],[{"math":true,"tex":"\\propto ","plain":"∝"}],[{"math":true,"tex":"\\rho ","plain":"ρ"}],[{"math":true,"tex":"\\rho ","plain":"ρ"}],[{"math":true,"tex":"\\propto  \\frac{1}{T}","plain":"∝ (1)/(T)"}]],"answer":[[{"text":"  The rise of liquid in a capillary tube is directly proportional to the surface tension and surface tension on a liquid’s surface is directly proportional to its density. "}],[{"text":"  When the temperature is increased, the density of the liquid will decrease, the surface tension on the liquid’s surface will decrease and consequently decrease the capillary rise. "}],[{"text":"  When the temperature is decreased, the density of the liquid will increase, the surface tension on the liquid’s surface will increase and consequently increase the capillary rise."}]]},{"label":"No.12","question":[[{"text":" Identify which property of water allows water to move against gravity. "}],[{"text":"  A. Capillary action allows water to move against gravity. "}],[{"text":"  B. Surface tension allows water to move against gravity. "}],[{"text":"  C. Cohesion allows water to move against gravity. "}]],"answer":[[{"text":"  A."}]]},{"label":"No.13","question":[[{"text":" Due to capillary action, a liquid will rise in a tube, if the angle of contact is "}],[{"text":"  A. acute   B. obtuse   C. 90° "}]],"answer":[[{"text":"  A. (rise - acute,  fall - obtuse,  no capillary action - 90°)"}]]},{"label":"No.14","question":[[{"text":" What will happen to the rise of liquid in a capillary tube if the radius of the tube is "}],[{"text":"  (i) increased (ii) decreased? "}]],"answer":[[{"text":"  (i) If the radius of the tube is increased, the rise  of liquid in capillary tube will decrease."}],[{"text":"  (ii) If the radius of the tube is decreased, the rise  of liquid in capillary tube will increase."}]]}],[{"label":"Rev.2","question":[[{"text":" What is the main source of energy? "}]],"answer":[[{"text":"  The main source of energy is solar energy (sun)."}]]},{"label":"Rev.3","question":[[{"text":" What are the main characteristics of fossil fuels? "}]],"answer":[[{"text":"  Fossil fuels are non-renewable sources of energy. "}],[{"text":"  Carbon is the main constituent of fossil fuels. "}],[{"text":"  A large amount of chemical energy is stored in the fossil fuels. "}],[{"text":"  They are made of dead plants and animals in conditions of high temperature and pressure."}],[]]},{"label":"Rev.7","question":[[{"text":" How does wind power generate electricity?"}]],"answer":[[{"text":" In a wind turbine, wind first hits the blades of the turbine, causing them to rotate and turn the turbine connected to them. That changes the kinetic energy to rotational energy, by rotating a shaft which is connected to a generator, and thereby producing electrical energy through electromagnetism."}]]},{"label":"No. 3","question":[[{"text":" Write difference between thermal power plant and hydropower plant."}]],"answer":[[{"text":"Thermal power plant | Hydropower plant"}],[{"text":"1. | Produces electricity by burning fossil fuels | Produces electricity by the flowing water."}],[{"text":"2. | Chemical energy stored in the fossil fuels is transformed into electricity. | Potential energy stored in the water is transformed into electricity."}],[{"text":"3. | Burning of fossil fuels pollute the air. | Blocking of water flow affects animals in the water."}],[{"text":"4. | Easier to build. | Harder to build."}],[{"text":"5. | Running cost is high. | Running cost is low."}]]},{"label":"No.1","question":[[{"text":"  Can we generate electricity from waterfall by using a turbine-generator? If it is possible, what are the necessary conditions?"}]],"answer":[[{"text":"  Yes, we can generate electricity from water fall by using a turbine-generator. "}],[{"text":"  The necessary conditions to generate electricity from waterfall –"}],[{"text":"   (i) sufficient amount of flowing water"}],[{"text":"   (ii) significant height difference between source and turbine"}]]},{"label":"No.6","question":[[{"text":"  Choose the correct answer."}],[{"text":"  (i) How does hydroelectric energy work?"}],[{"text":"   A. The water heats up and it turns into water vapor to power."}],[{"text":"   B. Water turns a piece similar to a propeller to power."}],[{"text":"   C. Water freezes and then is thrown to power it."}],[{"text":"  (ii) What principle pulls water into the penstock?"}],[{"text":"   A. Gravity, B. Force of the volume of water, C. Turbine."}],[{"text":"  (iii) Which is true for hydroelectric energy? "}],[{"text":"   A. It does not costs to build"}],[{"text":"   B. Water everywhere, it can be used everywhere."}],[{"text":"   C. It rains all the time."}]],"answer":[[{"text":"  (i). B,  (ii). A,  (iii). B. "}]]},{"label":"No.2","question":[[{"text":"  What are the major components of hydropower plants?"}]],"answer":[[{"text":"  Major components of hydropower plants are –"}],[{"text":"  (i) dam, (ii) turbine, (iii) generator, (iv) transformer, (v) transmission system."}]]},{"label":"No.4","question":[[{"text":"  State the changes in the form of energy while producing hydroelectricity."}]],"answer":[[{"text":"  gravitational potential energy "}],[{"math":true,"tex":"\\to ","plain":"→"}],[{"text":" kinetic energy "}],[{"math":true,"tex":"\\to ","plain":"→"}],[{"text":" electrical energy"}]]},{"label":"No.5","question":[[{"text":"  What is the main source of power of a hydroelectric power plant?"}]],"answer":[[{"text":"  The motion of water is the main source of power of a hydroelectric power plant."}]]},{"label":"Rev.9","question":[[{"text":" Why are wind and solar energies more popular than ocean energy?"}]],"answer":[[{"text":" - The energy potential from the ocean is quite large but the efficient commercial exploitation is difficult. "}],[{"text":" - Wind and solar energy can be obtained in many locations, but ocean energy can be obtained only in the ocean. စွမ်းအင်ရရှိနိုင်မှုအလားအလာများ၊ စီးပွားဖြစ်ထိထိရောက်ရောက်ထုတ်နိုင်ရန်ခက်ခဲ"}]]},{"label":"Rev.10","question":[[{"text":" What type of working fluids do closed-cycle ocean thermal energy conversion systems use?"}]],"answer":[[{"text":"  Closed-cycle ocean thermal energy conversion systems use volatile liquid such as ammonia as working fluids."}]]},{"label":"Rev.11","question":[[{"text":" What is geothermal energy?"}]],"answer":[[{"text":"  Geothermal energy is a type of renewable energy taken from the earth’s core (the internal heat of the earth) and it is one of the oldest types of natural sources of heat."}]]},{"label":"Rev.12","question":[[{"text":" How does geothermal heat get from the interior of the earth to the surface?"}]],"answer":[[{"text":"  Geothermal heat gets from the interior of the earth to the surface by pumping cool water into heated rocks where it is turned into steam, which then rises up to drive the turbines and generate electricity."}]]},{"label":"No.8","question":[[{"text":"  How is geothermal electricity produced?"}]],"answer":[[{"text":"  Wells of up to a mile deep or more are drilled into underground reservoirs to tap into the geothermal resources. These resources can be exploited from naturally occurring heat, rock and water permeability. Cooled water is pumped into heated rocks where it is turned into steam, which then rises up to drive the turbines and generate electricity. Condensed water is cooled and the process is repeated."}]]},{"label":"No.7","question":[[{"text":"  Why is geothermal energy considered as a renewable resource?"}]],"answer":[[{"text":"  Geothermal energy is considered as a renewable resource because it is natural heat generated and stored deep within the earth’s core."}]]},{"label":"No.9","question":[[{"text":"  What are the advantages of geothermal energy if compared to other energies?"}]],"answer":[[{"text":"  Advantages of geothermal energy if compared to other energies – "}],[{"text":"can be obtained from naturally occurring heat, rock and water permeability."}],[{"text":"no fuel required. "}],[{"text":"low ecological impact."}],[{"text":"renewable and sustainable."}]]},{"label":"Rev.13","question":[[{"text":" What is biomass?"}]],"answer":[[{"text":"  Biomass is renewable organic material that comes from plants and animals. Biomass contains stored chemical energy."}]]},{"label":"Rev.14","question":[[{"text":" Give the types of biomass energy sources."}]],"answer":[[{"text":"  The types of biomass energy sources are"}],[{"text":"Wood and wood processing wastes (eg. firewood, furniture mill sawdust and waste from pulp and paper mills)."}],[{"text":"Agricultural crops and waste materials (eg. corn, soybeans, sugar cane, woody plants, algae, rice husk and food processing residues)."}],[{"text":"Biogenic materials in municipal solid waste (eg. paper, cotton, wool products, food and wood wastes)."}],[{"text":"Animal manure and human sewage. "}]]},{"label":"Rev.15","question":[[{"text":" What are consequences of development on the environment? "}],[{"text":"  ဖွံ့ဖြိုးတိုးတက်လာမှု၏ ပတ်ဝန်းကျင်ပေါ် သက်ရောက်သောဆိုးကျိုးများ"}]],"answer":[[{"text":"  The consequences of development on the environment are global warming, air pollution, water pollution, acid rains, dangers posed by leaded fuels, gas leaks and explosions, climate change, deforestation."}]]},{"label":"No.13","question":[[{"text":" Why is it better to use more renewable energy resources rather than non-renewable resources?"}]],"answer":[[{"text":"  - Renewable energy resources are safe, abundant, and clean to use when compared  to fossil fuel."}],[{"text":"  - Renewable energy will never run out."}],[{"text":"  - The maintenance requirements of renewable energy are lower."}],[{"text":"  - Renewable energy has numerous health and environmental benefits."}],[{"text":"2024/ 2025 Past Paper"}],[{"text":"1. What are the three main elements of solar water heating systems installed in homes? How does it work?"}],[{"text":" Three main elements of solar water heating systems are the solar collector, insulated piping, and a hot water storage tank."}],[{"text":" The solar collector gathers the heat from solar radiation and transfers the heat to water. This heated water flow out of the collector to a hot water tank, and is used as necessary."}],[{"text":"2. Why is solar energy renewable? "}],[{"text":" Solar energy is renewable because it comes from the sun, which continuously produces energy through nuclear fusion and cannot be exhausted easily."}],[{"text":"3. What is the power conversion efficiency of the solar panel?"}],[{"text":" Power conversion efficiency of the solar panel is the ratio of the electrical power delivered by the panel to the solar power received by it."}],[{"text":"4. Give any two examples of the use of nuclear energy."}],[{"text":" - energy produced in a nuclear reactor can be harnessed to produce electricity."}],[{"text":" - nuclear energy is also being used to power submarines and ship."}],[{"text":" - radioisotopes in nuclear reactions are used in medicine, agriculture and research."}],[{"text":"5. State the changes in form of energy while producing (i) solar energy and (ii) geothermal energy."}],[{"text":" Solar energy:  light & thermal energy "}],[{"math":true,"tex":"\\to ","plain":"→"}],[{"text":" electrical energy"}],[{"text":" Geothermal:  thermal energy "}],[{"math":true,"tex":"\\to ","plain":"→"}],[{"text":"  kinetic energy "}],[{"math":true,"tex":"\\to ","plain":"→"}],[{"text":" electrical energy"}]]}],[{"label":"No.1","question":[[{"text":"  What is thermal conductivity? Express its unit in SI system."}]],"answer":[[{"text":"  The thermal conductivity of a material can be defined as the rate of heat transfer per unit area per unit temperature gradient."}],[{"text":"  In SI system, the unit of thermal conductivity is watt per metre per kelvin (Wm⁻¹K⁻¹)"}]]},{"label":"No.2","question":[[{"text":"  One end of a poker is placed in fire. After some time, the other end becomes hot. Explain how heat is transferred along the poker. Name the method of heat transfer in this case."}]],"answer":[[{"text":"  One end of a poker is placed in fire. After some time, the other end becomes hot. At first the end of a poker placed in fire gains heat energy. Then the handle end of the poker becomes hot by successive distribution of heat energy, among the adjacent parts."}],[{"text":"  The method of heat transfer in this case is heat conduction."}]]},{"label":"No.3","question":[[{"text":"  If a person wearing ordinary clothes travels out into space, the liquid in the body will boil. Why? Explain how a space suit can prevent this effect."}]],"answer":[[{"text":" Since atmospheric pressure in the space is much less than pressure on the earth, the boiling point in the space is much less than 100"}],[{"math":true,"tex":"℃","plain":"℃"}],[{"text":" and hence the liquid in the body will boil. "}],[{"text":" A space suit will keep the pressure to be normal and so the boiling point is not changed. A space suit is an insulator and it can prevent heat transfer between body and environment. In this way a space suit can prevent this effect."}]]},{"label":"No.4","question":[[{"text":"  In cold regions it is seen that birds on the branches of trees often ruffle their feathers. Explain the reason why the birds feel warm by ruffling their feathers."}]],"answer":[[{"text":"  In cold regions it is seen that birds on the branches of trees often ruffle their feathers."}],[{"text":"  By ruffling their feathers, air is trapped inside the feather. Air is a good insulator and it can prevent heat lost by conduction from the bird body. Hence, the birds feel warm."}]]},{"label":"No.5","question":[[{"text":"  How does a blanket wrapped round your body keep you warm on a cold day?"}]],"answer":[[{"text":" By wrapping the blanket, the air is trapped inside the blanket fibres. Air is a good insulator and it can prevent heat lost by conduction from our body.  Hence, we feel warm."}]]},{"label":"No.6","question":[[{"text":"  Explain with a diagram why an air conditioner should be the best positioned high, near the ceiling of a room. "}]],"answer":[[{"text":"  An air conditioner should be the best positioned high, near the ceiling of a room because air is cooled by air conditioner and as the cold air sink to bottom, it is replaced by warmer air rising from below. In this way, thermal energy is transformed in the whole of the room."}]]},{"label":"Rev.1","question":[[{"text":" Why does heat transfer take place between an object and its surrounding?"}]],"answer":[[{"text":"  Heat transfer takes place between an object and its surrounding because of temperature difference."}]]},{"label":"Rev.2","question":[[{"text":" What is the relation between the total emissive power of an object and total emissive power of black body when both are at same temperature?"}]],"answer":[[{"math":true,"tex":"ε","plain":"ε"}],[{"text":" = e "}],[{"math":true,"tex":"ε_{0}","plain":"ε₀"}],[{"math":true,"tex":"ε","plain":"ε"}],[{"text":"  = the total emissive power of an object"}],[{"math":true,"tex":"ε_{0}","plain":"ε₀"}],[{"text":" = the total emissive power of a black body"}],[{"text":"   e  = emissivity"}]]},{"label":"No.7","question":[[{"text":"  Why do we generally wear dark clothes in the winter and light-colored clothes in the summer?"}]],"answer":[[{"text":"  Generally, we wear dark clothes in the winter because dark color is a good absorber of heat and keep us comfortably warm during winter."}],[{"text":"  We wear light colour clothes in the summer because light colour is poor absorber of heat and our body is free from heat up."}]]},{"label":"No.8","question":[[{"text":"  Can you warm a kitchen in winter by leaving the oven door open?"}],[{"text":"  Can you cool the kitchen on a hot summer day by leaving the refrigerator door open? Explain."}]],"answer":[[{"text":"  Yes, it is possible to warm a kitchen in winter by leaving the oven door open after the oven is used. The hot air in the oven will transfer into the kitchen by heat convection and radiation."}],[{"text":"  No, it is impossible to cool the kitchen on a hot summer day by leaving the refrigerator door open. The work done by the refrigerator compressor will warm the room through exhaust instead of cooling it."}],[{"text":"oven ကို ဖွင့်ထားခြင်းဖြင့် ပူနေသောပစ္စည်းက အပူဖြာထွက်ကာ အခန်းကိုနွေးစေနိုင်တယ်။"}],[{"text":"ရေခဲသေတ္တာကို ဖွင့်ထားခြင်းဖြင့် အခန်းကိုအေးစေခြင်းမှာမဖြစ်နိုင်ပါ။ ရေခဲသေတ္တာကို ဖွင့်ထားခြင်းဖြင့် အခန်းထဲရှိပူသောလေများက ရေခဲသေတ္တာအတွင်းဝင်လာမည်။ ဝင်လာသော လေများအားလုံးကို အေးစေ ရန်အတွက် ရေခဲသေတ္တာရှိ compressor က များများအလုပ်လုပ်ရပြီး အပူထုတ်လွှတ်မှုပိုများလာမည်။ ရေခဲသေတ္တာကို ဖွင့်ထားခြင်းက အခန်းကိုပိုပူစေမည့်အပြင် compressor အလုပ်ပိုလုပ်ရသည့်အတွက် လျှပ်စစ်စွမ်းအင်ကိုဖြုန်းတီးရာရောက်သည်။ အခန်းအပူချိန်ကိုလည်းပိုမြင့်စေမည်။"}]]},{"label":"Rev.3","question":[[{"text":" How do heat transfer and internal energy differ?"}]],"answer":[[{"text":"  Heat transfer is energy in transit. Heat transfer is not stored as heat energy in a system. "}],[{"text":"  The internal energy of a system is the sum of the energies of all the constituent particles. The internal energy can be stored in a system."}]]},{"label":"Rev.4","question":[[{"text":" When heat transfers into a system, is the energy stored as heat? Explain briefly."}]],"answer":[[{"text":"  No, the energy is not stored as heat."}],[{"text":"  When heat transfers into a system, some of the heat does work and the rest is used to increase the internal energy of the system."}]]},{"label":"Rev.5","question":[[{"text":" Explain why the temperature of a gas increases when it is adiabatically compressed."}]],"answer":[[{"text":"  In an adiabatic process, there is no heat transfer. If a gas is compressed, work is done on the system and increase the internal energy. As the internal energy is a function of the temperature, the temperature will also increase."}]]},{"label":"No.17","question":[[{"text":" For a gas system, how much work is done in an isometric process? Explain."}]],"answer":[[{"text":"  The work done by the gas in an isometric process is zero. Because isometric process takes place at constant volume. So, the piston does not move. W = p "}],[{"math":true,"tex":"\\Delta ","plain":"Δ"}],[{"text":"V = 0"}],[]]},{"label":"No.20","question":[[{"text":"p1p2pressurevolume (L)"},{"text":" One liter of air is cooled at constant pressure until its volume is halved, and then it is allowed to expand isothermally back to its original volume. Draw the process on a p-V diagram. "}]],"answer":[[{"text":"isobaric compression"}],[{"text":"isothermal expansion"}]]},{"label":"Rev.6","question":[[{"text":" Is a temperature difference necessary to operate a heat engine? Explain why or why not."}]],"answer":[[{"text":"  Yes. A temperature difference is necessary to operate a heat engine. The work done by the heat engine is equal to the difference between the input heat from high temperature reservoir and output heat into the low temperature reservoir. W = QH - QC. Transferring heat only takes place between reservoir which have temperature difference."}],[{"text":"[OR]  For maximum efficiency, "}],[{"math":true,"tex":"\\frac{Q_{C}}{Q_{H}}","plain":"(QC)/(QH)"}],[{"text":" = "}],[{"math":true,"tex":"\\frac{T_{C}}{T_{H}}","plain":"(TC)/(TH)"}],[{"text":" ,  "}],[{"text":"  If TC = TH ,  "}],[{"math":true,"tex":"\\frac{Q_{C}}{Q_{H}}","plain":"(QC)/(QH)"}],[{"text":" = 1,  QC = QH"}],[{"math":true,"tex":"η","plain":"η"}],[{"text":" = 1- "}],[{"math":true,"tex":"\\frac{Q_{C}}{Q_{H}}","plain":"(QC)/(QH)"}],[{"text":" = 1 – 1 = 0"}],[{"text":"  If there is not temperature difference, a heat engine will not work at all."}]]},{"label":"No.16","question":[[{"text":" Mention the most important condition for a process to be reversible in thermodynamics."}]],"answer":[[{"text":"  The most important condition for a process to be reversible in thermodynamic is that the process should be carried out infinitesimally slowly and the driving force should be small enough to maintain the state of equilibrium."}]]}],[{"label":"Rev.1","question":[[{"text":" Why is the speed of sound higher in solids than liquids and gases?"}]],"answer":[[{"text":"  In solids, molecules are tightly bound together than liquids and gases. The distances between molecules in solids are very small and the energy of sound wave transfer quickly. Therefore, the speed of sound is higher in solids than liquids and gases."}],[{"text":"  Why does sound wave travel second fast in liquids?"}],[{"text":" - The distances between molecules in liquids are shorter than in gases, but longer than in solids. The energy of sound wave can transfer quickly in liquids than in gases, but slowly in liquids than in solids. So, sound wave travels second fast in liquids."}],[{"text":"  Why does sound wave travel slowest in gases than solids and liquids?"}],[{"text":" - The distances between molecules in gases are very far apart, compared with solids and liquids. The energy of sound wave can transfer slowly in gases than in solids and liquids. So, sound wave travels slowest in gases."}]]},{"label":"No.1","question":[[{"text":"  Sound travels faster in moist (or) humid air. Why is this?"}]],"answer":[[{"text":"  The density of moist air is less than that of dry air. As the velocity of sound in a gas is inversely proportional to the square root of its density, sound travels faster in moist (or) humid air than in dry air."}],[{"text":"လေမှာ အဓိကပါဝင်တဲ့ဓာတ်ငွေ့တွေက -"}],[{"text":"nitrogen- N₂ (78.08"}],[{"math":true,"tex":"\\%","plain":"%"}],[{"text":"), oxygen- O₂ (20.95"}],[{"math":true,"tex":"\\%","plain":"%"}],[{"text":"), argon – Ar (0.93"}],[{"math":true,"tex":"\\%","plain":"%"}],[{"text":"), greenhouse gases (0.04"}],[{"math":true,"tex":"\\%","plain":"%"}],[{"text":")"}],[{"text":"လေထုအတွင်း N₂ နှင့် O₂ တွေနေရာမှာ ရေငွေ့ (H₂O) တွေနေရာယူလာရင် Moist air ဖြစ်လာတယ်။"}],[{"text":"Molar mass of N₂ = 28 g mol⁻¹, Molar mass of O₂ = 32 g mol⁻¹, Molar mass of H₂O = 18 g mol⁻¹,"}],[{"text":"  ဒီတော့ H₂O ပါတဲ့စိုစွတ်လေတွေက mass နည်းလာတယ်၊ သိပ်သည်ခြင်းလည်းနည်းလာတယ်။ "}],[{"math":true,"tex":"\\rho =\\frac{m}{V}","plain":"ρ=(m)/(V)"}]]},{"label":"No.2","question":[[{"text":"  Name the factors on which the speed of sound in gas depends."}]],"answer":[[{"text":"  In gases, v = "}],[{"math":true,"tex":"\\frac{γ p}{\\rho }","plain":"(γ p)/(ρ)"}],[{"text":" . The speed of sound in a gas depends on"}],[{"text":"  adiabatic constant of gas, pressure in gas, density and temperature of the gas."}]]},{"label":"No.4","question":[[{"text":"  An astronaut on the Moon’s surface is unable to hear the sound of the rocket thrusters of his lunar lander craft. Which of the following is most likely to be correct explanation for this?"}],[{"text":" A. His helmet is sound proof."}],[{"text":" B. The sound made by the thruster is very soft."}],[{"text":" C. There is no atmosphere on the moon’s surface."}]],"answer":[[{"text":"  C. There is no atmosphere on the moon’s surface."}]]},{"label":"No.8","question":[[{"text":"  Define echo. Give its two applications."}]],"answer":[[{"text":"  An echo is the repetition of sound due to the reflection of sound. "}],[{"text":"  Two applications  (i) to find the depth of sea or distance of submarines. "}],[{"text":"     (ii) to estimate the distance of hills or mountains."}]]},{"label":"No.9","question":[[{"text":"  Why is the intensity of an echo less than that of the original sound? "}]],"answer":[[{"text":"  The intensity of an echo is less than that of the original sound because it is produced by a sound wave that travels through the air and then hits another surface. When it hits this surface, it loses energy."}]]},{"label":"Rev.4","question":[[{"text":" Why are the walls and roof of an auditorium covered with sound absorbent materials?"}]],"answer":[[{"text":"  The walls and roof of an auditorium are covered with sound absorbent materials because sound absorbing materials absorbs the sound waves and then help to reduce the multiple reflection of sound. (To reduce reverberation)"}]]},{"label":"Rev.5","question":[[{"text":" Why can infrasound not be heard by humans?"}]],"answer":[[{"text":"  The frequency of infrasound is lower than 20 Hz. Human can only hear sound of frequency between 20 Hz and 20 000 Hz. Thus, infrasound cannot be heard by humans. "}]]},{"label":"No.10","question":[[{"text":" Elephants and whales are known to use infrasound to communicate over very large distances. What are the advantages of infrasound for long distance communication?"}]],"answer":[[{"text":"  Since infrasound has lower frequency and longer wavelength, these are absorbed less in the atmosphere. Thus, infrasound cannot be easily attenuated and are helpful in communicating over long distances."}],[{"text":"Eg.6.  Elephants communicate over a long distance (up to 4 km) using sound with the fundamental frequencies as low as 15 Hz. A rhinoceros uses frequencies down to        10 Hz. "}],[{"text":"  (i) Why are elephants able to talk to one another over such a long distance? "}],[{"text":"  (ii) Can rhinoceros be able to communicate over long distances further than 4 km? Why?"}],[{"text":" (i) Infrasound waves (f < 20 Hz) have long wavelengths. They can travel over long distances. So, elephants are able to talk using frequencies as low as 15 Hz over long distances (up to 4 km)."}],[{"text":" (ii) Rhinoceros can be able to communicate over long distances further than 4 km because the lowest frequency they produced is 10 Hz which is less than 15 Hz and longer wavelength. Infrasound waves which have lower frequency and longer wavelengths are able to travel longer distances with less attenuation."}]]},{"label":"No.5","question":[[{"text":"  (i) Why is the ultrasound used in medical imaging rather than sound wave of audible frequencies or lower? "}]],"answer":[[{"text":" (i) The ultrasound is used in medical imaging rather than sound wave of audible frequencies or lower. Because ultrasound have higher frequency and shorter wavelength. Shorter wavelengths are more easily reflected or refracted in the superficial tissues than longer wavelengths. Thus, medical imaging used ultrasound gives better resolution."}]]},{"label":"No.14","question":[[{"text":" Is there a Doppler shift if the source and observer move in the same direction, with the same velocity? Explain."}]],"answer":[[{"text":"  No. The Doppler shift applies to relative motion. If the source and observer move in the same direction, with the same velocity, then there is no relative motion, and, hence, no Doppler effect."}]]},{"label":"Rev.9","question":[[{"text":" In terms of loudness and pitch, how would you compare the sounds made by a mosquito flying near your ear and the cracking of a toad?"}]],"answer":[[{"text":"  The sound made by a mosquito flying would have a higher pitch but quiet."}],[{"text":"   The sound made by the croaking of a toad would have a lower pitch but loud."}]]}],[{"label":"Rev.1","question":[[{"text":" Why must a camera lens be moved further from the film to focus on a closer object?"}]],"answer":[[{"text":"  Since converging lenses are used in cameras, the image distance would increase from the lens as the distance of the object decreases. Thus, a camera lens must be moved further from the film to get a sharp image for a closer object. "}]]},{"label":"Rev.2","question":[[{"text":" What are meant by farsightedness and nearsightedness and how can they be corrected?"}]],"answer":[[{"text":"  Farsightedness is a defect of vision in which distant objects are seen clearly, but objects nearby are blurry. This defect can be corrected by the use of spectacles with converging lens or convex lens."}],[{"text":"  Nearsightedness is a defect of vision in which near objects are seen clearly, but objects far away are blurry. This defect can be corrected by the use of spectacles with diverging lens or concave lens."}],[]]},{"label":"Rev.3","question":[[{"text":" Briefly explain the optical features of the human eye with labeled diagram."}]],"answer":[[{"text":"Eyelid: Since the eyelid opens and closes the eye, it is similar to the lens cover of the camera."}],[{"text":"Cornea: The front portion of the eye is covered by a tough, transparent membrane called cornea."}],[{"text":"Aqueous humour: The region between the cornea and the eyelens is filled with a transparent liquid called the aqueous humour."}],[{"text":"vitreous humour: The region between the eyelens and the retina contains a transparent liquid called the vitreous humour."}],[{"text":"Iris:  The iris which is the colored portion of the eye controls the amount of light energy entering the eye."}],[{"text":"Pupil: The pupil is in the centre of the iris and the light passes through it. It is similar to the aperture in the camera. The iris adjusts the size of the pupil in the eye.   "}],[{"text":"Ciliary muscles: The ciliary muscles are attached to the eyelens. The ciliary muscles can vary the thickness of the eyelens, thus alter the focal length of the lens to obtain a sharp image on the retina."}],[{"text":"Retina: The retina is the light sensitive area of the cells, at the back of the eye. The retina consists of rods and cones."}],[{"text":"  The yellow spot which is the most light-sensitive spot on the retina is used for viewing very small objects. Since the yellow spot consists of cones exclusively, the small objects can be seen clearly."}],[{"text":"  There is a spot on the retina which has no rods or cones. When an image is formed at this spot it cannot be seen at all. This spot is called the blind spot where the optic nerve enters the eye."}],[{"text":"  The light energy falling on the retina is transmitted to the brain by means of the optic nerve."}]]},{"label":"No.1","question":[[{"text":"  Name the essential parts of a human eye."}]],"answer":[[{"text":"  The essential parts of a human eye are –"}],[{"text":"  Eyelid, cornea, aqueous humour, iris, pupil, eyelens, ciliary muscles, vitreous humour, retina, and optic nerve. "}]]},{"label":"No.2","question":[[{"text":"  Discuss the important role of ciliary muscles for the eye."}]],"answer":[[{"text":"  The ciliary muscles are attached to the eyelens. The ciliary muscles can vary the thickness of the eyelens, thus alter the focal length of the lens to obtain a sharp image on the retina. "}]]},{"label":"No.3","question":[[{"text":"  State two defects of vision. Mention of the causes of the defects and corrections to these defects."}]],"answer":[[{"text":"  Two defects of vision are farsightedness (hyperopia) and nearsightedness (myopia)."}],[{"text":"-  For a person with farsightedness, the rays from near objects intersect at a point behind the retina after passing through the eyelens. "}],[{"text":" Cause: "}],[{"text":"  This is due to an eyeball which is too short or due to the eyelens which cannot be sufficiently convex. "}],[{"text":" Correction: "}],[{"text":"  This defect can be corrected by the use of spectacles with converging lens or convex lens."}],[{"text":"-  For a person with nearsightedness, the rays from distant objects intersect at a point in front of the retina after passing through the eyelens. "}],[{"text":" Cause: "}],[{"text":"  This is due to an eyeball which is too long or due to the eyelens which is more convex than is necessary."}],[{"text":" Correction: "}],[{"text":"  This defect can be corrected by the use of spectacles with diverging lens or concave lens."}]]},{"label":"No.4","question":[[{"text":"  Choose the correct answer from the following."}],[{"text":"  The yellow spot which is the most light-sensitive spot is -----------."}],[{"text":"  A. in the eyelens,  B. between the eyelens and retina,  C. on the retina"}]],"answer":[[{"text":"  C."}]]},{"label":"No.5","question":[[{"text":"  Choose the correct answer from the following."}],[{"text":"  For a farsighted person the rays from the near objects pass through the eyelens and intersect at a point -------------."}],[{"text":"  A. in front of the retina,  B. on the retina,  C. behind the retina."}]],"answer":[[{"text":"  C."}]]},{"label":"Rev.4","question":[[{"text":" The final image produced by the compound microscope cannot be projected. Why?"}]],"answer":[[{"text":"  Since the final image produced by the compound microscope is virtual image, it cannot be projected on the screen or wall."}],[]]},{"label":"No.6","question":[[{"text":"  Draw a ray diagram showing how the rays of light travel in a compound microscope."}]],"answer":[]},{"label":"No.7","question":[[{"text":"  A concave mirror instead of a lens is used as an objective in an astronomical telescope. Why?"}]],"answer":[[{"text":"  To obtain the sharp images of distant objects the objective should have a large diameter. In practice, it is difficult to make a perfect convex lens of large diameter free from defects so that a concave mirror instead of a convex lens is used as an objective."}]]},{"label":"No.8","question":[[{"text":"  How is a terrestrial telescope constructed to obtain the final image which is erect?"}]],"answer":[[{"text":"  In a terrestrial telescope a concave lens, instead of a convex lens, is used as an eyepiece to produce a final image which is erect."}]]},{"label":"No.9","question":[[{"text":"  Choose the correct answer."}],[{"text":"  In an optical fibre, the light is transmitted through the ----------."}],[{"text":"  A. core,  B. cladding, C. jacket."}]],"answer":[[{"text":"  A."}]]},{"label":"No.10","question":[[{"text":" Choose the correct answer."}],[{"text":"  The core of a fibre-optic cable is made of ------------."}],[{"text":"  A. Copper wire,  B. thin stand of glass,  C. lead wire."}]],"answer":[[{"text":"  B."}]]},{"label":"Rev.8","question":[[{"text":" What is the function of cladding in an optical fibre?"}]],"answer":[[{"text":"  The function of the cladding in an optical fibre is to provide a lower refractive index at the core interface in order to cause total internal reflection within the core so that light waves are transmitted through the fibre."}]]},{"label":"Rev.9","question":[[{"text":" Name the dispersion elements used in the optical spectrometer."}]],"answer":[[{"text":"  The dispersion elements used in the optical spectrometer are prism and grating."}]]},{"label":"Rev.10","question":[[{"text":" Mention the different types of spectrometers."}]],"answer":[[{"text":"  Three of the most common optical spectrometers are "}],[{"text":"  - spectrophotometers (UV-Vis spectrometer)"}],[{"text":"  - spectrofluorometers and"}],[{"text":"  - Raman spectrometers"}]]}],[{"label":"Rev.1","question":[[{"text":" How is the phase difference of two waves related to their path difference?"}]],"answer":[[{"text":"  The phase difference of two waves is directly proportional to their path difference."}],[{"math":true,"tex":"\\Delta ϕ","plain":"Δϕ"}],[{"text":" = "}],[{"math":true,"tex":"\\frac{2\\pi }{λ}","plain":"(2π)/(λ)"}],[{"math":true,"tex":"\\Delta  x","plain":"Δ x"}],[{"math":true,"tex":"\\Delta ϕ","plain":"Δϕ"}],[{"text":" = phase difference,"}],[{"math":true,"tex":"λ","plain":"λ"}],[{"text":" = wavelength,"}],[{"math":true,"tex":"\\Delta  x","plain":"Δ x"}],[{"text":" = the path difference."}]]},{"label":"Rev.2","question":[[{"text":" If the violet light in Young’s double slit experiment is replaced by red light, will the fringe width decrease or increase?"}]],"answer":[[{"text":"  fringe width,  "}],[{"math":true,"tex":"\\Delta ","plain":"Δ"}],[{"text":"y = "}],[{"math":true,"tex":"\\frac{λ D}{d}","plain":"(λ D)/(d)"}],[{"text":" ,  "}],[{"math":true,"tex":"\\Delta ","plain":"Δ"}],[{"text":"y "}],[{"math":true,"tex":"\\propto ","plain":"∝"}],[{"math":true,"tex":"λ","plain":"λ"}],[{"math":true,"tex":"λ_{red}","plain":"λred"}],[{"text":" > "}],[{"math":true,"tex":"λ_{violet}","plain":"λviolet"}],[{"text":" , "}],[{"math":true,"tex":"\\Delta y_{red}","plain":"Δyred"}],[{"text":" > "}],[{"math":true,"tex":"\\Delta y_{violet}","plain":"Δyviolet"}],[{"text":"  The experiment with red light will increase the fringe width."}]]},{"label":"No.1","question":[[{"text":"  Why is monochromatic coherent light used in the double slits experiment?"}]],"answer":[[{"text":"  Because monochromatic coherent light has single wavelength and phase, which produces a clear and distinct interference pattern without overlapping of multiple patterns."}]]},{"label":"No.2","question":[[{"text":"  What are the conditions for constructive interference and destructive interference?"}]],"answer":[[{"text":"  If the path difference is equal to an integral number of wavelengths (0, "}],[{"math":true,"tex":"λ","plain":"λ"}],[{"text":", 2"}],[{"math":true,"tex":" λ","plain":" λ"}],[{"text":", …,) the waves will interfere constructively."}],[{"text":"  If the path difference is equal to a half-integral number of wavelengths ("}],[{"math":true,"tex":"\\frac{λ}{2}","plain":"(λ)/(2)"}],[{"text":", "}],[{"math":true,"tex":"\\frac{3λ}{2}","plain":"(3λ)/(2)"}],[{"text":", "}],[{"math":true,"tex":"\\frac{5λ}{2}","plain":"(5λ)/(2)"}],[{"text":", …,) the waves will interfere destructively."}]]},{"label":"No.3","question":[[{"text":"  What will happen on the interference pattern of a double slit, if "}],[{"text":"  (i)  separation between the two slits is decreased? "}],[{"text":"  (ii) wavelength of light increased?"}]],"answer":[[{"text":"  fringe width, "}],[{"math":true,"tex":"\\Delta ","plain":"Δ"}],[{"text":"y = "}],[{"math":true,"tex":"\\frac{λ D}{d}","plain":"(λ D)/(d)"}],[{"text":" ,  "}],[{"math":true,"tex":"\\Delta ","plain":"Δ"}],[{"text":"y "}],[{"math":true,"tex":"\\propto ","plain":"∝"}],[{"math":true,"tex":"\\frac{λ}{d}","plain":"(λ)/(d)"}],[{"text":"   (if D is kept at constant)"}],[{"text":"  (i)  If separation between the two slits is decreased, the fringe width will increase. "}],[{"text":"  (ii) If wavelength of light is increased, the fringe width will increase."}]]},{"label":"Rev.3","question":[[{"text":" When the slit width in a single slit experiment is reduced, what will be affected on the diffraction pattern?"}]],"answer":[[{"text":"  Since y = m "}],[{"math":true,"tex":"\\frac{λ D}{a}","plain":"(λ D)/(a)"}],[{"text":", and y "}],[{"math":true,"tex":"\\propto  \\frac{1}{a}","plain":"∝ (1)/(a)"}],[{"text":"  When the slit width in a single slit experiment is reduced, the greater diffraction will occur and the larger the width of the central maximum will occur. "}]]},{"label":"Rev.4","question":[[{"text":" What is the difference between Fresnel diffraction and Fraunhofer diffraction?"}]],"answer":[[{"text":"  If the source of light and the screen are at a finite distance from the obstacle causing the diffraction, the diffraction is called Fresnel diffraction."}],[{"text":"  If the source of light and the screen are at an infinite distance from the obstacle causing the diffraction, the diffraction is called Fraunhofer diffraction."}]]},{"label":"Rev.5","question":[[{"text":" Why can a grating with smaller grating constant produce the wider the diffraction pattern?"}]],"answer":[[{"text":"  Since, d sin θ = m λ   and d = "}],[{"math":true,"tex":"\\frac{1}{N}","plain":"(1)/(N)"}],[{"text":"  If the grating constant N is small, distance between the slits d is large. (d = "}],[{"math":true,"tex":"\\frac{1}{N}","plain":"(1)/(N)"}],[{"text":" )"}],[{"text":"  For greater value of d, we can get larger order of maxima and wider the diffraction pattern. (m = "}],[{"math":true,"tex":"\\frac{d sin \\theta }{λ}","plain":"(d sin θ)/(λ)"}],[{"text":")"}]]},{"label":"Rev.6","question":[[{"text":" Why does the compact disc show the diffraction pattern?"}]],"answer":[[{"text":"  Because the tracks of a compact disc act as a diffraction grating, producing a separation of the colors of white light."}]]},{"label":"Rev.7","question":[[{"text":" What are the differences between the interference and diffraction?"}]],"answer":[[{"text":" | Interference | Diffraction"}],[{"text":"1. | If there are two or more waves, the interference can occur. | 1. | If there is only single wave, the diffraction can occur."}],[{"text":"2. | In interference, the amplitudes of the waves will change. | 2. | In diffraction, the amplitude of the wave will not change."}],[{"text":"3. | In interference, the direction of the waves will not change. | 3. | In diffraction, the direction of the wave will change."}]]},{"label":"Rev.8","question":[[{"text":" What is the difference between the diffraction grating and prism?"}]],"answer":[[{"text":" | Diffraction grating | Prism"}],[{"text":"1. | A diffraction grating is an optical device which consists of a large number of parallel slits of same width separated by equal opaque spaces. | 1. | A prism is transparent object which has two surfaces inclined to each other."}],[{"text":"2. | A diffraction grating can cause the dispersion of white light by the process of diffraction. | 2. | A prism can cause the dispersion of white light by the process of refraction."}],[{"text":"3. | Red colour is most deviated. | 3. | Red colour is least deviated."}],[{"text":"Violet colour is least deviated. | Violet colour is most deviated."}]]},{"label":"No.4","question":[[{"text":"  How are diffraction gratings used in spectrometers?"}]],"answer":[[{"text":"  Diffraction gratings are widely used as dispersive element in spectrometers."}]]}],[{"label":"Rev.1","question":[[{"text":" Which capacitor is used as tuning capacitor?"}]],"answer":[[{"text":"  Variable capacitors are used as tuning capacitor. "}]]},{"label":"Rev.2","question":[[{"text":" When the charge on a capacitor is increased, does its capacitance increase? Explain."}]],"answer":[[{"text":"  No. When the charge on a capacitor is increased, the potential difference also increases proportionally. Therefore, its capacitance is constant."}]]},{"label":"Rev.3","question":[[{"text":" A capacitor stores charge Q at a potential difference V. What happens if the voltage applied to the capacitor is doubled?"}]],"answer":[[{"text":"  The capacitance does not vary with applied voltage. "}],[{"text":"  According to Q = C V and Q "}],[{"math":true,"tex":"\\propto ","plain":"∝"}],[{"text":" V, if the voltage is doubled, the charge is also doubled."}]]},{"label":"No.1","question":[[{"text":"  State whether the following are True (T) or False (F)."}],[{"text":" (i) If one conductor of a capacitor has a charge + Q, the other has a charge – Q."}],[{"text":" (ii) The charge of the capacitor is the magnitude of the charge on each conductor."}],[{"text":" (iii) The potential difference of the capacitor is twice the potential difference between two conductors of the capacitor."}]],"answer":[[{"text":"  (i) True, (ii) True, (iii) False"}]]},{"label":"Rev.5","question":[[{"text":" When the distance between two parallel plates having the charges of equal magnitude and opposite sings is reduced, what will happen to the capacitance and potential difference of the plates?"}]],"answer":[[{"text":"  When the distance between two parallel-plates having the charges of equal magnitude and opposite sings is reduced, the capacitance is increased. Therefore, the potential difference across the plates must be reduced since the magnitude of charge on each plate does not change while capacitance increases."}],[{"text":"[OR]    Since, "}],[{"math":true,"tex":"C=\\frac{κ ε_{0} A}{d}","plain":"C=(κ ε₀ A)/(d)"}],[{"text":", if "}],[{"math":true,"tex":"κ ε_{0} A","plain":"κ ε₀ A"}],[{"text":" remain constant C "}],[{"math":true,"tex":"\\propto  \\frac{1}{d}","plain":"∝ (1)/(d)"}],[{"text":"  When distance d is reduced, capacitance C will increase. "}],[{"text":"  Since,  C = "}],[{"math":true,"tex":"\\frac{Q}{V}","plain":"(Q)/(V)"}],[{"text":"   if Q remain constant  C "}],[{"math":true,"tex":"\\propto  \\frac{1}{V}","plain":"∝ (1)/(V)"}],[{"text":"    When capacitance C increase, potential difference V will reduce."}]]},{"label":"Rev.6","question":[[{"text":" When an insulating material is inserted between the conductors of a capacitor in a vacuum, does its capacitance increase or decrease? Explain."}]],"answer":[[{"text":"  The capacitance will increase. The dielectric constant of an insulating material is greater than that of vacuum (air)."}],[{"text":"[OR]  * For vacuum or air, "}],[{"math":true,"tex":"κ","plain":"κ"}],[{"text":" = 1 and for other insulting material "}],[{"math":true,"tex":"κ","plain":"κ"}],[{"text":" > 1."}],[{"text":"  Since, "}],[{"math":true,"tex":"κ","plain":"κ"}],[{"text":" = "}],[{"math":true,"tex":"\\frac{C}{C_{0}}","plain":"(C)/(C₀)"}],[{"text":"  C = "}],[{"math":true,"tex":"κ","plain":"κ"}],[{"text":" C₀"}],[{"text":"  and "}],[{"math":true,"tex":"κ","plain":"κ"}],[{"text":" > 1,  C > C₀ "}],[{"math":true,"tex":"κ","plain":"κ"}],[{"text":" = dielectric constant of the insulating material"}],[{"text":"  C = capacitance of a capacitor with an insulating material"}],[{"text":"  C₀ = capacitance of the capacitor with a vacuum"}],[{"text":"  When an insulating material is inserted between the conductors of a capacitor in a vacuum, its capacitance will increase."}]]},{"label":"No.4","question":[[{"text":"  What must be done to increase the capacitance of a capacitor?"}]],"answer":[[{"text":"  Since, C = "}],[{"math":true,"tex":"\\frac{κ ε_{0} A}{d}","plain":"(κ ε₀ A)/(d)"}],[{"text":"  To increase the capacitance of a capacitor "}],[{"text":"the area of the conductors must be increased, "}],[{"text":"the distance between the two conductors must be reduced and "}],[{"text":"the insulating material having greater dielectric constant must be inserted between the two conductors."}]]},{"label":"No.5","question":[[{"text":"  How does a dielectric affect the maximum operating voltage of a capacitor even though the physical size of the capacitor does not change?"}]],"answer":[[{"text":"  A dielectric increases the maximum operating voltage of a capacitor even though the physical size of the capacitor doesn’t change. "}],[{"text":"  Why? / Explain."}],[{"text":"  The dielectric may be able to withstand a larger electric field (higher potential difference) between the plates than air."}]]},{"label":"Rev.8","question":[[{"text":" In capacitor charging and discharging, why is a resistor required to connect with the capacitor?"}]],"answer":[[{"text":"  A resistor is required to connect with the capacitor to slow down the charging and discharging processes."}]]},{"label":"Rev.9","question":[[{"text":" In which connection of the capacitors has each capacitor the same charge?"}]],"answer":[[{"text":"  In series connection, each capacitor has the same charge. "}]]},{"label":"Rev.10","question":[[{"text":" In which connection of the capacitors is the potential difference of each capacitor the same?"}]],"answer":[[{"text":"  In parallel connection, the potential difference of each capacitor is the same."}]]}],[{"label":"Rev.1","question":[[{"text":" What is meant by terminal voltage (available voltage) of a battery and how is it related to emf?"}]],"answer":[[{"text":"  The potential difference across the terminals of a battery connected to an external circuit is called the terminal voltage (or available voltage) of the battery."}],[{"text":"The terminal voltage of a battery when "}],[{"text":"  (i) discharging (in use)   V = E – I r"}],[{"text":"  (ii) open circuit (not in use)  V = E  ("}],[{"math":true,"tex":"∵","plain":"∵"}],[{"text":" I = 0)"}],[{"text":"  (iii) charging    V = E + I r"}]]},{"label":"Rev.2","question":[[{"text":" What are (i) open circuit and (ii) closed circuit? Illustrate with diagrams."}]],"answer":[[{"text":"  (i) An open circuit is a circuit in which the path is incomplete which means there  is no flow of current."}],[],[{"text":"  (ii) A closed circuit is a circuit in which the path is complete and there is a flow of  current in the entire path."}]]},{"label":"No.1","question":[[{"text":"  How is electricity produced by an electric cell?"}]],"answer":[[{"text":"  Electricity is produced by an electric cell by converting chemical energy to electrical energy."}]]},{"label":"No.2","question":[[{"text":"  In an electric circuit, which component is used for (i) supply electricity, (ii) close (or) open the electric circuit, (iii) providing a path for the flow of electric current?"}]],"answer":[[{"text":"  (i)  Battery supply electricity"}],[{"text":"  (ii) Switch close (or) open the electric circuit"}],[{"text":"  (iii) Connecting wire provide a path for the flow of electric current"}]]},{"label":"No.3","question":[[{"text":"  Can the terminal voltage of a battery ever exceed its emf? If so, explain the necessary condition?"}]],"answer":[[{"text":"  No, the terminal voltage of a battery cannot ever exceed its emf. The terminal voltage of a battery can only exceed its emf when it is charging. "}],[{"text":"  (i) discharging (in use)   V = E – I r (V < E)"}],[{"text":"  (ii)  open circuit (not in use)  V = E"}],[{"text":"  (iii) charging    V = E + I r (V > E)"}],[{"text":"Eg.3.  What is the difference between electromotive force (emf) and potential difference (voltage)?"}],[{"text":"  Electromotive force (emf) is amount of energy provided by the battery per unit charge to move round the complete circuit."}],[{"text":"  The potential difference or voltage is the amount of energy required to move a unit charge from one end to another end of a circuit element. "}]]},{"label":"Rev.3","question":[[{"text":" What are the advantages and disadvantages of (i) the series aiding connection of batteries (ii) the parallel connection of batteries?"}]],"answer":[[{"text":"  (i) In series aiding, "}],[{"text":" Advantages : The resultant emf increase. "}],[{"text":" Disadvantage : Since the internal resistances of the batteries are in series, the resultant internal resistance is increased. So, the electric current is decreased."}],[{"text":" (ii) In parallel"}],[{"text":" Advantages : Since the internal resistances of the batteries are in parallel, the resultant internal resistance is decreased. So, the electric current is increased."}],[{"text":" Disadvantage : The resultant emf of parallel combination is just the emf of a single battery."}]]},{"label":"No.7","question":[[{"text":"  With two identical batteries, how would you arrange the bulbs and batteries in a circuit to get the maximum possible total power out? (Assume the batteries have negligible internal resistance.)"}],[]],"answer":[[{"text":"  The light bulbs should be connected in parallel. Batteries should be connected in series aiding."}],[{"text":"ဘက်ထရီတွေကို series aiding ဆက်ခြင်းကြောင့် emf ပိုများလာမယ်။ မီးသီးတွေကို parallel ဆက်ခြင်းကြောင့် ရရှိသောဗို့အားတူညီကြတယ်။ ဘက်ထရီ seriesတွဲမှထုတ်ပေးနိုင်တဲ့အမြင့်ဆုံးဗိုအားကို မီးသီးအားလုံးက တူညီစွာရရှိမယ်။ "}]]},{"label":"Rev.5","question":[[{"text":" Which quantity determines the rate at which electrical energy is delivered by a current?"}]],"answer":[[{"text":"  Electrical power determines the rate at which electrical energy is delivered by a current."}]]},{"label":"No.8","question":[[{"text":"  What is electrical energy? Express its unit."}]],"answer":[[{"text":"  Electrical energy is energy associated with the flow of charge through any part of circuit."}],[{"text":"  The SI unit of electrical energy is joule (J). "}],[{"text":"  The practical unit of electrical energy is kilowatt hour (kWh)."}]]},{"label":"No.9","question":[[{"text":"  (i) Define electrical power. (ii) Write down the unit of electrical power. (iii) How many joules are there in 1 kWh?"}]],"answer":[[{"text":"  (i) Electrical power is the rate of transfer of electrical energy."}],[{"text":"  (ii) The unit of electrical power P is the watt (W). "}],[{"text":"  (iii) 1 kWh = 10³ W × 1 h = 10³ J s⁻¹ × 3600 s = 3.6 × 10⁶ J    "}]]},{"label":"No.14","question":[[{"text":" Why is electrical energy transformed into heat energy when a current flows through a resistor?"}]],"answer":[[{"text":"  Electrical energy is transformed into heat energy when a current flows through a resistor. It is because the electrons collide with the atoms in the resistor when they pass through it. Hence the atoms acquire additional energy and therefore heat energy is produced."}]]},{"label":"Rev.7","question":[[{"text":" On which factors does the heat produced in a current carrying conductor depend?"}]],"answer":[[{"text":"  According to Joule’s law of electricity and heat, H = "}],[{"math":true,"tex":"\\frac{I^{2} R t}{J}","plain":"(I² R t)/(J)"}],[{"text":"  The heat produced in a current carrying conductor depends on "}],[{"text":"   (i) the current flowing through the conductor,"}],[{"text":"   (ii) the value of resistance of the conductor,"}],[{"text":"   (iii) the time taken by the current to pass through the conductor."}]]},{"label":"No.13","question":[[{"text":" State the Joule’s law of electricity and heat."}]],"answer":[[{"text":"  The amount of heat produced in a resistor due to a current flowing through it is directly proportional to the square of the current, the value of resistance and the time taken by the current to pass through the resistor."}],[{"text":"  H = "}],[{"math":true,"tex":"\\frac{I^{2} R t}{J}","plain":"(I² R t)/(J)"}],[{"text":" Where, H = amount of heat"}],[{"text":"    I  = current "}],[{"text":"    R = resistance of the resistor "}],[{"text":"    t  = time taken"}],[{"text":"    J = Joule’s mechanical equivalent of heat (J = 4.2 J cal⁻¹)"}],[{"text":"No.11 Two heaters of the same power and the same resistance are used to heat the water. In which of the following cases will the water heat up faster? (i) if heaters are connected in series (ii) if heaters are connected in parallel."}],[{"text":"  Two heaters have the same power and the same resistance."}],[{"text":"  Let the resistance of two heaters = R₁ = R₂ = R"}],[{"text":"  (i) If heaters are connected in series,  "},{"math":true,"tex":"R_{series}","plain":"R_(series)"},{"text":"  = R₁ + R₂ = R + R "}],[{"text":"   "},{"math":true,"tex":"R_{series}","plain":"R_(series)"},{"text":"  = 2 R"}],[{"text":"   Heat produced by flowing current I in the heaters for time taken t,"}],[{"text":"    "},{"math":true,"tex":"H_{series}","plain":"H_(series)"},{"text":" = "}],[{"math":true,"tex":"\\frac{V^{2} t}{R_{series} J}","plain":"(V² t)/(Rseries J)"}],[{"text":"    "},{"math":true,"tex":"H_{series}","plain":"H_(series)"},{"text":" = "}],[{"math":true,"tex":"\\frac{V^{2} t}{2 R J}","plain":"(V² t)/(2 R J)"}],[{"text":"  (ii) If heaters are connected in parallel, "}],[{"math":true,"tex":"\\frac{1}{R _{parallel}}","plain":"(1)/(R parallel)"}],[{"text":" = "}],[{"math":true,"tex":"\\frac{1}{R_{1}}","plain":"(1)/(R₁)"}],[{"text":" + "}],[{"math":true,"tex":"\\frac{1}{R_{2}}","plain":"(1)/(R₂)"}],[{"text":"    = "}],[{"math":true,"tex":"\\frac{1}{R}","plain":"(1)/(R)"}],[{"text":" + "}],[{"math":true,"tex":"\\frac{1}{R}","plain":"(1)/(R)"}],[{"math":true,"tex":"\\frac{1}{R _{parallel}}","plain":"(1)/(R parallel)"}],[{"text":" = "}],[{"math":true,"tex":"\\frac{2}{R}","plain":"(2)/(R)"}],[{"text":"   "},{"math":true,"tex":"R_{parallel}","plain":"R_(parallel)"},{"text":" = "}],[{"math":true,"tex":"\\frac{R}{2}","plain":"(R)/(2)"}],[{"text":"   Heat produced by flowing current I in the heaters for time taken t,"}],[{"text":"    "},{"math":true,"tex":"H_{parallel}","plain":"H_(parallel)"},{"text":" = "}],[{"math":true,"tex":"\\frac{V^{2} t}{R_{parallel} J}","plain":"(V² t)/(Rparallel J)"}],[{"text":"    "},{"math":true,"tex":"H_{parallel}","plain":"H_(parallel)"},{"text":" = "}],[{"math":true,"tex":"\\frac{V^{2} t}{\\frac{R}{2} J}","plain":"(V² t)/((R)/(2) J)"}],[{"text":" = "}],[{"math":true,"tex":"\\frac{2 V^{2} t}{R J}","plain":"(2 V² t)/(R J)"}],[{"math":true,"tex":"\\frac{H_{parallel}}{H_{series}}","plain":"(Hparallel)/(Hseries)"}],[{"text":" = "}],[{"math":true,"tex":"\\frac{\\frac{2 V^{2} t}{R J}}{\\frac{V^{2} t}{2 R J}}","plain":"((2 V² t)/(R J))/((V² t)/(2 R J))"}],[{"text":" = "}],[{"math":true,"tex":"\\frac{2 V^{2} t}{R J} \\times  \\frac{2 R J}{V^{2} t}","plain":"(2 V² t)/(R J) × (2 R J)/(V² t)"}],[{"math":true,"tex":"\\frac{H_{parallel}}{H_{series}}","plain":"(Hparallel)/(Hseries)"}],[{"text":" = 4"}],[{"text":"   "},{"math":true,"tex":"H_{parallel}","plain":"H_(parallel)"},{"text":" = 4 "},{"math":true,"tex":"H_{series}","plain":"H_(series)"},{"text":" "}],[{"text":"  Heating is four times faster in parallel connection. So, if heaters are connected in parallel, the water will heat up faster."}]]},{"label":"No.12","question":[[{"text":" Which draws more current, a 100 W light bulb or a 75 W light bulb when connected to a main line? Which has higher resistance?"}]],"answer":[[{"text":"  When a 100 W light bulb and a 75 W light bulb are connected to a main line, they have same voltage. "}],[{"text":"  Since, P = V I.  If V is constant, P "}],[{"math":true,"tex":"\\propto ","plain":"∝"}],[{"text":" I. So, 100 W light bulb will draw more current."}],[{"text":"  Since, P = "}],[{"math":true,"tex":"\\frac{V^{2}}{R}","plain":"(V²)/(R)"}],[{"text":".  If V is constant, P "}],[{"math":true,"tex":"\\propto  \\frac{1}{R}","plain":"∝ (1)/(R)"}],[{"text":". So, 75 W light bulb has higher resistance."}]]},{"label":"No.10","question":[[{"text":" Why do we use fuses in an electric circuit?"}]],"answer":[[{"text":"  We use fuses in an electric circuit to prevent electrical appliances from being damage if excessive current flows through them."}]]},{"label":"No.20","question":[[{"text":" Which of the following metals cannot be used as fuse wire? "}],[{"text":"  A. iron, B. silver, C. tin-lead alloy"}]],"answer":[[{"text":"  Iron cannot be used as fuse wire."}],[{"text":"သံရဲ့အရည်ပျော်မှတ်က 1538"}],[{"math":true,"tex":"℃","plain":"℃"}],[{"text":", ငွေရဲ့အရည်ပျော်မှတ်က 961.8"}],[{"math":true,"tex":"℃","plain":"℃"}],[{"text":", သံဖြူခဲ သတ္တုစပ်ရဲ့ အရည်ပျော်မှတ်က 215"}],[{"math":true,"tex":"℃","plain":"℃"}],[{"text":" သံကအရည်ပျော်မှတ်မြင့်လို့ ဖျူးအဖြစ်အသုံးမပြုနိုင်ဘူး။ သတ္တုတွေအားလုံးထဲမှာ ငွေက လျှပ်စစ်စီး ကူးမှုအကောင်းဆုံး(လျှပ်စစ်ခုခံမှုအနည်းဆုံး)ဖြစ်တယ်။ တန်ဖိုးလည်းမြင့်မားတယ်။ ငွေကိုလည်းဖျူးအဖြစ် မသုံးနိုင်ဘူး။ သံဖြူနှင့် ခဲသတ္တုစပ်ကိုတော့ ဖျူးအဖြစ်အသုံးပြုနိုင်တယ်။ (အရည်ပျော်မှတ်နိမ့်ပြီး လျှပ်စစ် ခုခံမှုများတယ်)။"}],[{"text":"  Which of the following metals is used as fuse wire?   Correct Ans is only C."}]]},{"label":"No.21","question":[[{"text":" Why should the material used for fuse have low melting point?"}]],"answer":[[{"text":"  The material used for a fuse wire must have a low melting point so that it melts as soon as excessive current flows through it. Thus, it can prevent the appliance from being damage."}]]}],[{"label":"Rev.1","question":[[{"text":" What is the major difference between AC and DC current?"}]],"answer":[[{"text":"  In direct current (DC), the electrons flow steadily in the same direction all the time. "}],[{"text":"  In alternating current (AC), the direction of the flow of electrons changes periodically."}]]},{"label":"Rev.2","question":[[{"text":" Why is AC current better than DC in long distance distribution of electrical power?"}]],"answer":[[{"text":"  The inevitable loss of energy that occurs when current is distributed over long distances is far smaller with alternating current than with direct current."}]]},{"label":"Rev.3","question":[[{"text":" Is the current from the outlet of telephone charger, AC or DC?"}]],"answer":[[{"text":"  The current from the outlet of telephone charger is DC."}]]},{"label":"Rev.4","question":[[{"text":" Differentiate between the magnetic flux and magnetic flux density."}]],"answer":[[{"text":"  Magnetic flux "}],[{"math":true,"tex":"∅_{B}","plain":"∅B"}],[{"text":" is a measurement of the total magnetic lines of force which passes through a surface area. It is scalar."}],[{"text":"  The magnetic flux density or magnetic induction "}],[{"math":true,"tex":"\\vec{B}","plain":"B⃗"}],[{"text":" is the number of magnetic lines of force passing perpendicularly through a unit area of material. It is vector."}]]},{"label":"No.2","question":[[{"text":"  (i) What is electromagnetic induction? "}],[{"text":"  (ii) State the methods by which an induced emf can be produced in a coil."}]],"answer":[[{"text":" (i) A current flows through a loop of wire whenever there is a change in the magnetic lines of force trough the loop. This phenomenon is called electromagnetic induction."}],[{"text":"  (ii) The methods by which an induced emf can be produced in a coil - "}],[{"text":"switching the current in another coil near it ON and OFF,"}],[{"text":"moving the current-carrying coil near it,"}],[{"text":"moving the magnet near it,"}]]},{"label":"No.5","question":[[{"text":"  Explain how magnetic flux passing through a surface can be zero when the magnetic field is not zero."}]],"answer":[[{"text":"  Although the magnetic field is not zero, magnetic flux passing through a surface can be zero when the magnetic field, "}],[{"math":true,"tex":"\\vec{B}","plain":"B⃗"}],[{"text":" is parallel to the surface area, and perpendicular to the d"}],[{"math":true,"tex":"\\vec{A}","plain":"A⃗"}],[{"text":", "}],[{"math":true,"tex":"\\theta ","plain":"θ"}],[{"text":" = 90"}],[{"math":true,"tex":"^{\\circ}","plain":"°"}],[{"text":" Hence, "}],[{"math":true,"tex":"ϕ_{B}","plain":"ϕB"}],[{"text":" = B A cos 90"}],[{"math":true,"tex":"^{\\circ}","plain":"°"}],[{"text":" = 0"}]]},{"label":"No.6","question":[[{"text":"  Discuss the factors determining the induced emf in a closed loop of wire."}]],"answer":[[{"text":"  Since   E = - N "}],[{"math":true,"tex":"\\frac{d ϕ_{B}}{d t}","plain":"(d ϕB)/(d t)"}],[{"math":true,"tex":"ϕ_{B}","plain":"ϕB"}],[{"text":" = B A cos θ"}],[{"text":"  The induced emf in a closed loop of wire depends on "}],[{"text":"  -  The number of turns N in the wire loop,"}],[{"text":"  - The rate of change of magnetic flux "}],[{"math":true,"tex":"\\frac{dϕ_{B}}{dt}","plain":"(dϕB)/(dt)"}],[{"text":","}],[{"text":"  - The strength of magnetic field B,"}],[{"text":"  - The area of the wire loop A, "}],[{"text":"  - The angle (θ) between the magnetic field "}],[{"math":true,"tex":"\\vec{B}","plain":"B⃗"}],[{"text":" and area vector d"}],[{"math":true,"tex":"\\vec{A}","plain":"A⃗"}],[{"text":"."}]]},{"label":"No.7","question":[[{"text":"  (i) Does the induced emf in a circuit depend on the resistance of the circuit? "}],[{"text":"  (ii) Does the induced current depend on the resistance of the circuit?"}]],"answer":[[{"text":"  (i) No, the induced emf in a circuit does not depend on the resistance of the circuit."}],[{"text":"  (ii) Yes, the induced current depends on the resistance of the circuit."}]]},{"label":"Rev.5","question":[[{"text":" Why is Faraday’s law important?"}]],"answer":[[{"text":"  Faraday's law is important because it explains how electromagnetic induction works. This phenomenon is the basic for modern technologies such as electric motors, generators and transformers. Without understanding it, it is impossible to use the electrical energy nowadays."}]]},{"label":"Rev.6","question":[[{"text":" What does negative sign indicate in Faraday’s law of electromagnetic induction formula?"}]],"answer":[[{"text":"  The negative sign in Faraday's law of electromagnetic induction formula indicates the direction of the induced emf. The induced emf is always in a direction that opposes the change in the original magnetic flux that causes it."}]]},{"label":"No.3","question":[[{"text":"  Suggest any two ways to increase the output voltage of an AC generator."}]],"answer":[[{"text":"  The output voltage of an AC generator can be increased by "}],[{"text":"increasing the speed of rotation of the coil,"}],[{"text":"increasing the area of the coil,"}],[{"text":"increasing the number of turns in the coil,"}],[{"text":"using stronger magnets."}]]},{"label":"No.4","question":[[{"text":"  In an AC generator, the speed at which the coil rotates is tripled. How would this affect (i) the frequency (ii) the maximum output voltage?"}]],"answer":[[{"text":"   In an AC generator, the speed at which the coil rotates is tripled."}],[{"text":"  (i)  the frequency of AC current will also triple."}],[{"text":"  (ii) the maximum output voltage will also triple."}]]},{"label":"Rev.7","question":[[{"text":" What devices must be used to deliver (i) thousands of voltage at the terminals of a sparking plug of motorcar engine using a 12 V battery (ii) 12 V AC from 220 V AC mains?"}]],"answer":[[{"text":"  (i) Induction coil  (ii) step-down transformer"}]]},{"label":"Rev.8","question":[[{"text":" Explain each of the following: "}],[{"text":"  (i) A transformer will not work on DC. "}],[{"text":"  (ii) The core of a transformer needs to be laminated. "}],[{"text":"  (iii) If a transformer increases voltage, it reduces current."}]],"answer":[[{"text":" (i) Transformer works on the basic principle of electromagnetic induction. When an alternating AC current passes through the primary coil of transformer, it creates a constantly changing magnetic field which in turn induces the alternating current in the secondary coil."}],[{"text":"  However, direct current (DC) does not have the required alternating nature to generate a changing magnetic field. Thus, transformer will not work on DC."}],[{"text":" (ii) The core of a transformer needs to be laminated to reduce the flow eddy currents."}],[{"text":" (iii) power input = power output"}],[{"text":"  Vp Ip = Vs Is"}],[{"text":"  As the product of voltage and current is the same on both coils of a transformer, a transformer which increases the voltage will reduce the current in the same proportion, and vice versa."}]]},{"label":"Rev.9","question":[[{"text":" (i)  Which type of transformer must be used to change a high current and a low  alternating voltage into a lower current and a higher alternating voltage?"}],[{"text":"  (ii) Which type of transformer must be used to change a low current and a high  alternating voltage into a higher current and a lower alternating voltage?"}],[{"text":"  (iii) Which type of transformer is used in a welding machine? Why?"}]],"answer":[[{"text":"  (i) step-up transformer"}],[{"text":"  (ii) step-down transformer"}],[{"text":"  (iii) In step-down transformer, Vs < Vp Is > Ip"}],[{"text":"  This larger secondary current is very useful in welding process. That is why   step-down transformer is used for welding machine."}]]},{"label":"No.1","question":[[{"text":"  What is a transformer? How does a step-up transformer differ from a step-down transformer?"}]],"answer":[[{"text":"  A transformer is an inductive electrical device that used to change the voltage of an alternating current."}],[{"text":"  The step-up transformer increases the output voltage and reduce the output current."}],[{"text":"  The step-down transformer reduces the output voltage and increase the output current."}]]},{"label":"Rev.10","question":[[{"text":" Explain why AC rather than DC is used for transmitting electrical power."}]],"answer":[[{"text":"  AC rather than DC is used for transmitting electrical power because AC voltage can be stepped up by using transformer to reduce the power loss over long transmission lines."}]]},{"label":"Rev.11","question":[[{"text":" Why are the lamps connected in parallel in the lighting circuit?"}]],"answer":[[{"text":"  Since the lamps are connected in parallel in the lighting circuit, the other lamps are not affected when one lamp is switched ON or OFF. This means that the lamps continue to be ON no matter what is done to the other lamps."}]]},{"label":"Rev.12","question":[[{"text":" Why are the fuses and switches placed on the live wire of the circuit?"}]],"answer":[[{"text":"  The live wire carries a high voltage. So, the fuses and switches are placed on the live wire of the circuit to protect the appliances used in the circuit."}]]},{"label":"Rev.13","question":[[{"text":" Mention the appropriate wiring circuit for the following electrical appliances (i) bulb and fluorescent lamp (ii) electric iron (iii) water pump motor (iv) electric stove."}]],"answer":[[{"text":"  (i)  bulb and fluorescent lamp should be in lighting circuit."}],[{"text":"  (ii)  electric iron should be in heating circuit."}],[{"text":"  (iii) water pump motor should be in power circuit."}],[{"text":"  (iv) electric stove should be in heating circuit."}]]},{"label":"No.8","question":[[{"text":"  Why are ordinary circuit breakers and fuses not effective in preventing shocks?"}]],"answer":[[{"text":"  Ordinary circuit breakers and fuses are not effective in preventing shocks because the current that causes them to trip is greater than the maximum value of safe current that a human body can withstand."}]]},{"label":"Rev.14","question":[[{"text":" Which quantity determines whether you receive an electrical shock?"}]],"answer":[[{"text":"  The amount of electric current determines whether we receive an electrical shock. The human body can only withstand up to about 50 mA."}]]},{"label":"Rev.15","question":[[{"text":" What causes the overheating of cable?"}]],"answer":[[{"text":"  The extremely large amount of current flowing in the conducting wires under certain conditions, such as short circuit or overloading causes overheating of cables."}],[{"text":"2024/ 2025 Past Paper"}],[{"text":"1. What are the magnetic parameters that you have known?"}],[{"text":" The magnetic parameters are magnetic flux density, magnetic field strength, magnetic flux."}],[{"text":"2. How many types of transformers are there? Which type of transformer is used in a welding machine?"}],[{"text":" There are two types of transformers. They are step-up transformer and step-down transformer. Step-down transformer is used in a welding machine."}]]}],[{"label":"Rev.1","question":[[{"text":" Where are LEDs used?   LED အသုံးပြုရာနယ်ပယ်များကိုဖော်ပြပါ။"}]],"answer":[[{"text":"  - LEDs are typically used as ON/OFF indicator lights in electrical appliances such  as televisions, VCR, video cameras, computers, and stereos."}],[{"text":"  - They are used to display numbers in alarm clocks, radios, and microwave ovens."}],[{"text":"  - They are also used for very large video displays at sporting events and concerts."}]]},{"label":"Rev.2","question":[[{"text":" Describe some applications of LEDs.  LED ၏ အသုံးပြုမှုအချို့ကိုဖော်ပြပါ။"}],[]],"answer":[[{"text":"  An LED indicator circuit is one of the main applications of LED. A current limiting resistor should be connected in series with LED in the circuit to protect the LED. The value of the series resistance should be chosen that the voltage drop at LED must be nearly equal to that at the limiting resistor."}],[]]},{"label":"Rev.4","question":[[{"text":" Give the symbol, circuit diagram and explain the function of a photodiode."}],[]],"answer":[[{"text":"  When the photodiode is illuminated with light (photons) of energy h "}],[{"math":true,"tex":"ν","plain":"ν"}],[{"text":" greater than the energy gap Eg of the semiconductor, then electron-hole pairs are generated due to absorption of photons. When an external load is connected, the current flows. This current is called photocurrent."}]]},{"label":"Rev.5","question":[[{"text":" What effect does an increase of light intensity on LDR have on its resistance?"}]],"answer":[[{"text":"  An increase of light intensity on LDR decreases its resistance."}]]},{"label":"No.1","question":[[{"text":"  Which electrical component is used to control the brightness of street lamps?"}],[{"text":"  (i) LED (ii) LDR (iii) thermistor"}]],"answer":[[{"text":"  (ii) LDR."}]]},{"label":"Rev.7","question":[[{"text":" What is thermistor? What is the main difference between NTC and PTC thermistor?"}]],"answer":[[{"text":"  A thermistor is a temperature sensor that exhibits a large change in resistance proportional to a change in temperature. It can therefore convert changes in temperature into changes in electric current."}],[{"text":"  As the temperature increases, resistance of the NTC thermistor decreases. "}],[],[{"text":"  As the temperature increases, resistance of the PTC thermistor increases."}]]},{"label":"No.4","question":[[{"text":"  A student uses the sensor in the circuit shown in figure. The LED lights up when the temperature reaches 40 ℃. Name a suitable temperature sensor and draw its circuit symbol."}]],"answer":[[{"text":"  Thermistor can be used as a temperature sensor. "}],[],[{"text":"  Circuit symbol of thermistor"}]]},{"label":"Rev.8","question":[[{"text":" What is the disadvantage of LCD displays?"}]],"answer":[[{"text":"  The disadvantages of LCD displays are -"}],[{"text":"  -  limited viewing angle."}],[{"text":"  - produces heat and consumes much electrical energy."}],[{"text":"  - a polarizing glass filter is needed."}],[{"text":"  - have difficulty producing black and very dark grays."}],[{"text":"  - not suitable for the bright environment."}]]},{"label":"No.5","question":[[{"text":"  In the giving table, P, Q, R and S are the outputs of four logic gates. Name the logic gate which represents each output."}],[{"text":"Input | Output"}],[{"text":"A | B | P | Q | R | S"}],[{"text":"0\n0\n1\n1 | 0\n1\n0\n1 | 0\n0\n0\n1 | 0\n1\n1\n1 | 1\n1\n1\n0 | 1\n0\n0\n0"}]],"answer":[[{"text":" The output P is AND gate. The output Q is OR gate. The output R is NAND gate. The output S is NOR gate."}]]},{"label":"Rev.9","question":[[{"text":"Heat sensorLight sensorRelay and heater"},{"text":" State the names of the two types of logic gate used in flowing figure. Explain what happens to the outputs of the three logic gates when "}],[{"text":"  (i) it is cold (0) and dark (0), "}],[{"text":"  (ii) it is cold (0) and bright (1)."}]],"answer":[[{"text":"  Two NOT gates and one AND gate."}],[{"text":"  (i) when it is cold (0) and dark (0), the relay and heater start running (1)."}],[],[{"text":"  (ii) when it is cold (0) and bright (1), the relay and heater do not run (0)."}]]},{"label":"No.6","question":[[{"text":"  Figure shows a control system which may be fitted in an automatic washing machine. What conditions will (i) start (ii) stop the washing machine working?"}]],"answer":[[{"text":" (i) The washing machine will start working (ON = 1) when all of the switches are (1) state. power switch is ON (1), door switch is CLOSED (1) and water level switch is FULL (1)."}],[{"text":" (ii) The washing machine will stop working (OFF = 0) either one or two or all of the switches are (0) state. power switch is OFF (0), door switch is OPEN (0) and water level switch is EMPTY (0)"}]]},{"label":"No.3","question":[[{"text":"ANDParking lightLight = 1Dark = 0Light sensorON/ OFF switchON = 1OFF = 0"},{"text":"  A car may be fitted with an automatic parking light which switches ON when the car is parked at night. Figure shows an incomplete system for a parking light. Copy and complete the figure to show how a NOT gate can be used to make the parking light work. Use the correct symbol for a NOT gate. "}],[],[{"text":"System switch ကိုဖွင့်ထားလျက် ညအချိန် ကား parking ထိုးလျှင် မီးလင်းစေလိုသည်။ မီးလင်းစေလိုပါ က output logic 1 ဖြစ်ရမည်။ AND gate ကိုသုံးထားခြင်းကြောင့် input အားလုံး logic 1 ဖြစ်နေမှ ရမည်။"}],[{"text":"switch ON ထားမည် logic 1 ဖြစ်သည်။ လင်းစေလိုသည့် အချိန်သည် ညအချိန်ဖြစ်သည်။ light sensor logic 0 ဖြစ်နေသည်။ ထို့ကြောင့် inverter (NOT) ကိုသုံးကာ light sensor logic ကို 1 သို့ ပြောင်းရမည်။ "}]],"answer":[[{"text":"ANDParking lightLight = 1Dark = 0Light sensorON/ OFF switchON = 1OFF = 0"}],[{"text":"A"}],[{"math":true,"tex":"\\bar{A}","plain":"A̅"}],[{"text":"BZ = "}],[{"math":true,"tex":"\\bar{A}","plain":"A̅"}]]},{"label":"Rev.11","question":[[{"text":" + B"},{"text":" For the circuit below, write the value of Z as a Boolean expression, using A and B."}]],"answer":[[{"text":"  Z = "}],[{"math":true,"tex":"\\bar{A}","plain":"A̅"}],[{"text":" + B"}]]},{"label":"No.8","question":[[{"text":"  Draw the logic circuit represented by each of the following expressions: "}],[{"text":"  (i) A + B + C (ii) ABC   (iii) AB + C   (iv) AB + CD"}]],"answer":[[{"text":"A + B + CABCABCABC"},{"text":"  (i) A + B + C (ii) ABC"}],[{"text":"ABABAB + CCABBACDAB + CDCD  (iii) AB + C (iv) AB + CD"}]]},{"label":"Rev.12","question":[[{"text":" Give a short note on communication system."}]],"answer":[[{"text":"  In general, an electronic communication system is composed of the transmission, reception, and processing of information between two or more locations with the use of electronic circuits. The basic components of an electronic communication system are the transmitter, communication channel or medium receiver and noise (as a source of disturbance)."}]]},{"label":"Rev.13","question":[[{"text":" Write short notes on the components of a simple radio receiver."}]],"answer":[[{"text":"  The radio receiver comprises roughly six pieces. They are antenna, tuner, rf (radio frequency) amplifier, diode detector, af (audio frequency) amplifier and speaker. "}],[{"text":"The receiving antenna picks up the radio signals."}],[{"text":"Tuning circuit select a particular radio frequency."}],[{"text":"Radio frequency amplifier amplifies the radio frequency signal."}],[{"text":"Diode detector demodulates audio signal from carrier wave."}],[{"text":"Audio frequency amplifier amplifies the demodulated audio frequency signal."}],[{"text":"The speaker produces the amplified sound."}]]},{"label":"No.12","question":[[{"text":" Can sound travel very far? Why? Which device can be used to transmit sounds over long distance? What range of frequencies do the radio waves have?"}]],"answer":[[{"text":"  No, sound cannot travel very far because its waves lose energy as they travel."}],[{"text":"  A radio transmitter, a part of a radio communication system used electromagnetic waves (radio waves) is used to transmit sounds over long distance."}],[{"text":"  Frequency range of radio waves is 3 kHz - 300 GHz"}]]},{"label":"No.13","question":[[{"text":" What is meant by “AM and FM”?"}]],"answer":[[{"text":"  When the amplitude of high frequency carrier wave is changed in accordance with the intensity of the signal, it is called amplitude modulation (AM)."}],[{"text":"  When the frequency of carrier wave is changed in accordance with the intensity of the signal, it is called frequency modulation (FM)."}]]},{"label":"No.14","question":[[{"text":" What are the differences between FM and AM? Explain with illustrative diagrams?"}]],"answer":[[{"text":" | FM | AM"}],[{"text":"(i) | The amplitude of carrier wave remains constant with modulation. | (i) | The amplitude of carrier wave changes with modulation."}],[{"text":"(ii) | The carrier frequency changes according to the strength of the modulating signal. | (ii) | The carrier amplitude changes according to the strength of the modulating signal."}],[{"text":"(iii) | The carrier frequency changes with modulation. | (iii) | The carrier frequency remains constant with modulation."}],[{"text":"(iv) | FM radio ranges in a higher spectrum from 88 to 108 MHz. (or) 1200 to 2400 bits per second. | (iv) | AM radio ranges from 535 to 1705 kHz (or) up to 1200 bits per second."}]]},{"label":"No.15","question":[[{"text":" Which range of frequency a radio telephone or walkie talkie is communicating? Also, find the corresponding wavelength."}]],"answer":[[{"text":"  Generally, a radio telephone or walkie talkie use a frequency range 136 MHz to 900 MHz."}],[{"text":"  Since, v = f "}],[{"math":true,"tex":"λ","plain":"λ"}],[{"text":", "}],[{"math":true,"tex":"λ","plain":"λ"}],[{"text":" = "}],[{"math":true,"tex":"\\frac{v}{f}","plain":"(v)/(f)"}],[{"text":",  For radio wave, v = c = 3 "}],[{"math":true,"tex":"\\times ","plain":"×"}],[{"text":" 108 m s-1"}],[{"text":"  For, f = 136 MHz, "}],[{"math":true,"tex":"λ","plain":"λ"}],[{"text":" = "}],[{"math":true,"tex":"\\frac{v}{f}","plain":"(v)/(f)"}],[{"text":" = "}],[{"math":true,"tex":"\\frac{3 \\times  10^{8}}{136 \\times  10^{6}}","plain":"(3 × 10⁸)/(136 × 10⁶)"}],[{"text":" = 2.205 m"}],[{"text":"  For, f = 900 MHz, "}],[{"math":true,"tex":"λ","plain":"λ"}],[{"text":" = "}],[{"math":true,"tex":"\\frac{v}{f}","plain":"(v)/(f)"}],[{"text":" = "}],[{"math":true,"tex":"\\frac{3 \\times  10^{8}}{900 \\times  10^{6}}","plain":"(3 × 10⁸)/(900 × 10⁶)"}],[{"text":" = 0.33 m"}]]}],[{"label":"Rev.1","question":[[{"text":" Compare the ionizing and penetrating powers of alpha, beta and gamma rays."}]],"answer":[[{"text":"  Alpha rays are the most ionizing of the three rays."}],[{"text":"  Beta rays are less ionizing than alpha rays."}],[{"text":"  Gamma rays are the least ionizing of the three rays."}],[{"text":"  Alpha rays are the least penetrating of the three rays."}],[{"text":"  Beta rays are more penetrating than alpha rays."}],[{"text":"  Gamma rays are the most penetrating of the three rays."}]]},{"label":"No.1","question":[[{"text":"  What is radioactivity? Who discovered radioactivity? Name some radioactive elements. "}]],"answer":[[{"text":"  Radioactivity"}],[{"text":"  The emission of some or all of alpha, beta and gamma rays from the nucleus of an unstable atom is called radioactivity."}],[{"text":"  Henri Becquerel discovered radioactivity."}],[{"text":"  Some radioactive elements are uranium, thorium, radium, polonium and radon."}]]},{"label":"No.2","question":[[{"text":"  Are all elements in nature radioactive? Can radioactive elements be produced artificially?"}]],"answer":[[{"text":"  No. Not all elements in nature are radioactive. Only a few heavy elements with atomic number greater than 83 are radioactive or unstable."}],[{"text":"  Yes, radioactive elements can be produced artificially."}]]},{"label":"No.3","question":[[{"text":"  Briefly describe alpha decay, beta decay and gamma decay. "}]],"answer":[[{"text":"  page – 199 definition 2, 3, 4 / page -200 definition 7"}]]},{"label":"No.4","question":[[{"text":"  What are alpha, beta and gamma rays? Briefly describe their properties? "}]],"answer":[[{"text":"  page – 201 – properties of "}],[{"math":true,"tex":"\\alpha ","plain":"α"}],[{"text":", "}],[{"math":true,"tex":"β","plain":"β"}],[{"text":", "}],[{"math":true,"tex":"γ","plain":"γ"}]]},{"label":"No.5","question":[[{"text":"  Explain the terms activity and half-life of a radioactive substance. "}]],"answer":[[{"text":" The rate of decay of a radioactive sample is called activity."}],[{"text":" The half-life is defined as the time for half the atoms in a radioactive sample to decay."}],[]]},{"label":"No.6","question":[[{"text":"  What is meant by radon has a half-life of 3.8 days? Draw a graph to illustrate the half-life of radon."}]],"answer":[[{"text":"  “Radon has a half-life of 3.8 days” means that the time for half the atoms in radon to decay is 3.8 days."}]]},{"label":"Rev.3","question":[[{"text":" What is carbon dating? How does the proportion of the carbon-14 in the remains of dead plants and animals gives clues about their age? Can the age of living plants and animals be determined by carbon dating method?"}]],"answer":[[{"text":"  Carbon dating "}],[{"text":"  Carbon dating is a technique for estimating the age of the remains of plants and animals by measuring the activity of carbon-14 presents in the remains."}],[{"text":"  when an animal or a plant dies, carbon cycle stops and the carbon-14 in the remain gradually decreases by radioactive decay. By measuring the activity of carbon-14, the age of the remain can be estimated."}],[{"text":"  No, the age of living plants and animals cannot be determined by carbon dating method. "}]]},{"label":"Rev.4","question":[[{"text":" Aluminium is rolled into sheets 1 mm thick. Of three types of radiations; alpha, beta and gamma, which radiation is suitable for checking the uniformity of thickness. Give the reason for your answer."}]],"answer":[[{"text":"  Beta radiation is suitable for checking the uniformity of thickness in rolling aluminium into sheets 1 mm thick."}],[{"text":"  Alpha rays have very low penetrating power and thus very few or no alphas will pass through the monitoring material."}],[{"text":"  Gamma rays have very high penetrating power and thus almost all gamma rays will pass through it. No different counts will occur."}]]},{"label":"No.9","question":[[{"text":"  What are radioisotopes? Give some examples. "}]],"answer":[[{"text":"  Radioisotope"}],[{"text":"  A radioisotope (radioactive isotope or radionuclide) is an atom with an unstable nucleus which undergoes radioactive decay, resulting in the emission of alpha, beta and gamma rays."}],[{"text":"  iodine-131, phosphorus-32, cobalt-60, cesium-137, carbon-14, potassium-40"}]]},{"label":"No.10","question":[[{"text":"  What is a tracer? State some uses of radioactive tracers. Why is it important to use radioactive tracers with short half-lives in medical diagnosis?"}]],"answer":[[{"text":"  Tracer"}],[{"text":"  A tracer is a small amount of radioactive isotope introduced into a system in order to follow the behaviour of some components of that system."}],[{"text":"  Usage of radioactive tracers"}],[{"text":"  In medicine  - to check thyroid function."}],[{"text":"  In industry  - to monitor fluid flow, detect leaks, and to study the rate of  wear, erosion and corrosion of equipment."}],[{"text":"  In agriculture - to estimate the amount of fertilizers that should be supplied to  soil."}],[{"text":"  It important to use radioactive tracers with short half-lives in medical diagnosis so that there is no detectable radiation after a few days and no danger for the users."}]]},{"label":"No.11","question":[[{"text":"  Give two medical applications of radioisotopes. "}]],"answer":[[{"text":"  Two medical applications of radioisotopes are "}],[{"text":"   (i)  checking the function of body organs,"}],[{"text":"   (ii) killing cancer cells in a tumor, "}]]},{"label":"Rev.5","question":[[{"text":" What device is a nuclear reactor? Give a brief description of the essential component of a nuclear reactor."}]],"answer":[[{"text":"  Nuclear reactor"}],[{"text":"  Nuclear reactor is a device in which a fission chain reaction can be initiated, maintained and controlled."}],[{"text":"Fissionable nuclear fuel : is the material for fission reaction to take place. Uranium-235 or plutonium-239 can be used as fuel."}],[{"text":"Moderator : is a material to slow down fast neutrons released from a fission process. Graphite and ordinary water (H₂O) as well as heavy water (D₂O) are used as moderators."}],[{"text":"Coolant  : is to extract the heat produced by fission fragments when they slow down and stop in the reactor material. Water and carbon dioxide CO₂ gas are used as coolant."}],[{"text":"Control rods : are used to control the rate of reaction by raising or lowering them from the core. Boron and cadmium (neutron absorbing materials) are used as control rods. "}],[{"text":"Reactor vessel : contains reactor core, moderator, coolant and control rods. It is a pressurized steel vessel."}],[{"text":"Shielding  : (or containment structure) is a protective barrier, usually a dense material. It reduces the passage of radiations from radioactive materials by absorbing them."}]]},{"label":"No.12","question":[[{"text":"  What is meant by radioactive wastes? What is their impact on environment? "}]],"answer":[[{"text":"  Radioactive waste"}],[{"text":"  Materials which are radioactive and for which there is no further use are called radioactive waste."}],[{"text":"  Radioactive wastes that release from nuclear power plant can remain radioactive and dangerous to human health for thousands of years. Radioactive waste storage is mostly a problem."}]]},{"label":"Rev.6","question":[[{"text":" How is the de Broglie wavelength of electrons related to the quantization of their orbits in atoms?"}]],"answer":[[{"text":"  An integral number of de Broglie wavelengths associated with a revolving electron must fit in the circumference of an orbit."}],[{"text":"  In symbols, 2 "}],[{"math":true,"tex":"\\pi ","plain":"π"}],[{"text":" r = n "}],[{"math":true,"tex":"λ","plain":"λ"}],[{"text":" where n = 1,2,3,4 ……. (integer)"}],[{"text":"  Where r = radius of orbit, "}],[{"math":true,"tex":"λ","plain":"λ"}],[{"text":" = de Broglie wavelength of electron"}]]}]];
